window.EXPLICACIONES = Object.assign(window.EXPLICACIONES || {}, {

/* ==================== ENDOCRINOLOGÍA Y METABOLISMO ==================== */
'MIR-2021-M169': {
  esp:'Medicina Interna', tema:'Nefrología', sub:'SIADH por antidepresivos',
  clave:'Hiponatremia EUVOLÉMICA con natriuria de 45 en una paciente con sertralina: SIADH. Restricción hídrica y retirar el fármaco.',
  exp:'El diagnóstico se construye en dos pasos. Primero la *volemia*: no hay edemas ni hipotensión, es decir, la paciente está *euvolémica*, lo que descarta tanto la hipovolemia como los estados edematosos. Segundo la *natriuria*: 45 mEq/L, es decir, *inapropiadamente alta* para una hiponatremia, lo que significa que el riñón sigue eliminando sodio en lugar de retenerlo, como haría si le faltara volumen. Esa combinación —hiponatremia euvolémica con natriuria elevada y sin diuréticos— define un *SIADH*, y el responsable está a la vista: los *ISRS* como la sertralina son una de las causas farmacológicas más frecuentes de SIADH, sobre todo en mujeres ancianas y en las primeras semanas de tratamiento. El tratamiento es la *restricción hídrica* y la retirada o sustitución del fármaco, corrigiendo *despacio*: no más de 8 a 10 mEq en 24 horas, por el riesgo de mielinólisis pontina. El *suero salino hipertónico* se reserva para la hiponatremia con síntomas *graves* —convulsiones, coma— o cifras muy bajas, y aquí la clínica es un cuadro confusional en una paciente estable con sodio de 126.',
  no:{0:'La enfermedad de Addison cursaría con HIPERpotasemia, hipotensión e hiperpigmentación; aquí el potasio es normal y la tensión también.',1:'El salino hipertónico se reserva para síntomas graves como convulsiones o coma, o para hiponatremias muy profundas.',3:'La diabetes insípida produce HIPERnatremia por pérdida de agua libre, exactamente lo contrario de lo que hay aquí.'},
  trampa:'Se olvida revisar la lista de fármacos. Antes de estudiar un SIADH conviene mirar el tratamiento del paciente: ISRS, carbamazepina, antipsicóticos y diuréticos son los sospechosos habituales.',
  dx:['SIADH farmacológico','Insuficiencia suprarrenal','Hiponatremia por diuréticos','Polidipsia primaria'],
  obj:'Diagnosticar el SIADH por volemia y natriuria y tratarlo con restricción hídrica.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con las guías europeas sobre hiponatremia.'
},
'MIR-2021-M171': {
  esp:'Medicina Interna', tema:'Endocrinología', sub:'Agranulocitosis por antitiroideos',
  clave:'Fiebre y dolor de garganta en un paciente con metimazol: agranulocitosis hasta que se demuestre lo contrario. Suspender y pedir hemograma.',
  exp:'Es una de las reglas de seguridad más importantes de la endocrinología: a todo paciente que empieza *metimazol o propiltiouracilo* hay que advertirle de que si aparece *fiebre o dolor de garganta* debe suspender el fármaco y acudir para un *hemograma con recuento diferencial urgente*. La razón es la *agranulocitosis*, una reacción idiosincrásica que ocurre en torno al 0,2-0,5% de los tratados, con más frecuencia en los *primeros tres meses*, exactamente el momento en que se encuentra esta paciente. Su presentación más habitual es precisamente una faringitis febril, y si se trata como una amigdalitis banal sin mirar el hemograma se pierde un tiempo que puede costar la vida, porque el paciente queda sin defensa frente a infecciones bacterianas. Ante neutrófilos por debajo de 500 hay que retirar el antitiroideo *definitivamente*, ingresar, iniciar antibioterapia de amplio espectro y valorar factores estimulantes de colonias; el hipertiroidismo se controlará después con yodo radiactivo o cirugía, nunca con el otro antitiroideo, porque la reactividad es cruzada.',
  no:{0:'Tratar como una faringitis estreptocócica sin hemograma puede dejar pasar una agranulocitosis mortal.',1:'La prueba rápida de estreptococo no descarta la causa más peligrosa en este contexto concreto.',2:'El propranolol no produce agranulocitosis; el fármaco que hay que suspender es el metimazol.'},
  trampa:'Se trata la garganta y se olvida la médula. En un paciente con antitiroideos, fiebre más faringitis significa hemograma inmediato.',
  dx:['Agranulocitosis por metimazol','Faringoamigdalitis estreptocócica','Tiroiditis'],
  obj:'Reconocer la agranulocitosis por antitiroideos y actuar de inmediato.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías de la American Thyroid Association sobre hipertiroidismo.'
},
'MIR-2021-M173': {
  esp:'Medicina Interna', tema:'Endocrinología', sub:'Criterios diagnósticos de diabetes',
  clave:'Dos glucemias basales por encima de 126 en días distintos (153 y 136) ya son diagnósticas: no hace falta ninguna prueba más.',
  exp:'Los criterios diagnósticos de diabetes son cuatro y basta con *uno* de ellos, confirmado en una segunda ocasión si el paciente está asintomático: *glucemia basal igual o superior a 126 mg/dL*, *glucemia a las dos horas de la sobrecarga con 75 g igual o superior a 200*, *hemoglobina glicada igual o superior al 6,5%*, o una *glucemia al azar igual o superior a 200 con síntomas cardinales*. Este paciente tiene *dos determinaciones basales por encima de 126* —153 y 136— en días distintos, de modo que ya cumple el criterio *confirmado* y el diagnóstico está hecho. La tercera cifra, 118, corresponde a una glucemia alterada en ayunas, pero no anula las otras dos. Pedir una sobrecarga oral o una glicada no sería incorrecto en términos de seguridad, pero es *innecesario*: retrasa el inicio del tratamiento y consume recursos. Y la *glucosuria negativa* no significa nada, porque el umbral renal de glucosa está en torno a 180 mg/dL.',
  no:{0:'La sobrecarga oral es innecesaria cuando ya existen dos glucemias basales diagnósticas.',2:'La insulinemia y el péptido C sirven para clasificar el tipo de diabetes, no para diagnosticarla.',3:'La glicada es un criterio alternativo, pero no hace falta cuando el diagnóstico ya está confirmado por glucemia basal.'},
  trampa:'Se pide una prueba más "para estar seguros". Dos basales por encima de 126 en días distintos ya son el diagnóstico: lo que toca es tratar.',
  dx:['Diabetes mellitus tipo 2','Glucemia alterada en ayunas','Diabetes secundaria'],
  obj:'Aplicar los criterios diagnósticos de diabetes sin pruebas innecesarias.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con los estándares de la ADA.'
},
'MIR-2021-M174': {
  esp:'Medicina Interna', tema:'Infectología', sub:'Enfermedad de Chagas',
  clave:'Estreñimiento crónico rebelde MÁS palpitaciones y disnea: pensar en Chagas. La pregunta clave es de dónde procede el paciente.',
  exp:'La combinación de una *alteración motora digestiva* rebelde con una *cardiopatía* incipiente en un adulto joven o de mediana edad debe hacer pensar en la *enfermedad de Chagas*, causada por *Trypanosoma cruzi*. En su fase crónica el parásito destruye los *plexos nerviosos autónomos*, y de ahí salen sus dos grandes síndromes: el *digestivo*, con *megacolon* —que se manifiesta como estreñimiento crónico resistente a todo— y megaesófago con disfagia; y el *cardiaco*, la miocardiopatía chagásica, que produce trastornos de conducción —bloqueo de rama derecha con hemibloqueo anterior izquierdo es el patrón clásico—, arritmias con palpitaciones, insuficiencia cardiaca y aneurisma apical. La pregunta correcta es de una sencillez engañosa: *preguntar por el país de procedencia*, porque el Chagas es endémico en América Latina continental y sin ese dato epidemiológico nadie solicita la serología. Es un excelente recordatorio de que una anamnesis dirigida orienta más que cualquier prueba, y de que en República Dominicana el diagnóstico diferencial de estos cuadros incluye enfermedades que no aparecen en los textos europeos.',
  no:{0:'El electrocardiograma mostrará alteraciones, pero no da el diagnóstico etiológico: solo confirma que hay cardiopatía.',1:'El enema opaco puede mostrar el megacolon, pero tampoco explica por qué está ahí.',2:'El ecocardiograma cuantifica la afectación cardiaca, no su causa.'},
  trampa:'Se piden pruebas para cada síntoma por separado. Lo que une el estreñimiento con las palpitaciones es la epidemiología, y eso se pregunta.',
  dx:['Enfermedad de Chagas','Hipotiroidismo','Miocardiopatía dilatada','Estreñimiento funcional'],
  obj:'Sospechar Chagas ante la asociación de megacolon y cardiopatía, y priorizar la anamnesis epidemiológica.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con Mandell, Enfermedades Infecciosas, y documentos de la OPS.'
},
'MIR-2021-M192': {
  esp:'Medicina Interna', tema:'Endocrinología', sub:'Hipercolesterolemia poligénica',
  clave:'Colesterol moderadamente alto, sin xantomas y SIN familiares con enfermedad cardiovascular: hipercolesterolemia poligénica.',
  exp:'Las dislipemias hereditarias se separan por la magnitud de las cifras, la presencia de signos físicos y, sobre todo, por la *historia familiar*. Aquí las cifras son *moderadas* —colesterol total entre 247 y 298, triglicéridos entre 150 y 216, HDL normal—, *no hay xantomas* y, el dato decisivo, *ningún familiar tiene enfermedad cardiovascular*: los padres llegan a los 80 y tantos y los dos hermanos están sanos. Eso hace muy improbable una dislipemia monogénica. Lo que queda es una *hipercolesterolemia poligénica*, la forma más frecuente con diferencia, en la que múltiples variantes genéticas de efecto pequeño se combinan con factores ambientales —aquí el *tabaquismo intenso* y un consumo de *6 unidades de alcohol al día*, que explica también los triglicéridos—. Que el paciente haya tenido un infarto no cambia el diagnóstico de la dislipemia: lo explica su acumulación de factores de riesgo. Lo que sí cambia es el objetivo terapéutico, porque ahora está en prevención secundaria y necesita estatina de alta intensidad además de dejar el tabaco y el alcohol.',
  no:{0:'La disbetalipoproteinemia eleva colesterol y triglicéridos de forma paralela y muy marcada, con xantomas palmares estriados.',1:'La hipercolesterolemia familiar heterocigota daría un LDL mucho más alto, xantomas tendinosos e historia familiar de eventos precoces.',2:'La hiperlipemia familiar combinada exige agregación familiar con fenotipos variables, y aquí los familiares están sanos.'},
  trampa:'Se diagnostica una dislipemia hereditaria por el infarto precoz. Sin historia familiar ni xantomas ni cifras extremas, lo probable es lo poligénico.',
  dx:['Hipercolesterolemia poligénica','Hipercolesterolemia familiar','Hiperlipemia familiar combinada','Dislipemia secundaria'],
  obj:'Diferenciar la hipercolesterolemia poligénica de las formas monogénicas.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías ESC/EAS sobre dislipemias.'
},
'MIR-2021-M196': {
  esp:'Medicina Interna', tema:'Endocrinología', sub:'Hipercolesterolemia por colestasis',
  clave:'Colesterol de 800 en una hepatopatía colestásica: es SECUNDARIO. El colesterol se elimina por la BILIS, no por el riñón.',
  exp:'Aunque las cifras impresionen —colesterol total de 800 y LDL de 395—, la causa está a la vista y es *secundaria*. El colesterol se elimina fundamentalmente por vía *biliar*, ya sea directamente o transformado en ácidos biliares; cuando existe una *colestasis*, esa vía se bloquea y el colesterol se acumula, además de aparecer una lipoproteína anómala llamada *lipoproteína X*, característica de la colestasis, que los laboratorios cuentan dentro del LDL y por eso las cifras se disparan. La clínica lo acompaña: *prurito intenso*, típico del acúmulo de sales biliares, y *xantomas* cutáneos por depósito. Por eso no procede ningún estudio genético ni etiquetar de hipercolesterolemia familiar homocigota, que además tendría un fenotipo completamente distinto —cifras similares o mayores pero desde la infancia, con xantomas tendinosos, arco corneal y enfermedad coronaria muy precoz—. El tratamiento es el de la *hepatopatía de base*, y sobre el prurito la colestiramina; las estatinas se emplean con cautela en la hepatopatía colestásica y no son la prioridad.',
  no:{1:'El test genético no es imprescindible: la causa secundaria es evidente y explica por completo el perfil lipídico.',2:'La homocigota se manifiesta desde la infancia con xantomas tendinosos y coronariopatía precoz, y no cursa con colestasis ni prurito.',3:'La eliminación del colesterol es fundamentalmente BILIAR, no renal: ese es justamente el mecanismo del caso.'},
  trampa:'La cifra altísima arrastra hacia lo genético. En presencia de colestasis, un colesterol de 800 se explica solo con la obstrucción de su vía de salida.',
  dx:['Hipercolesterolemia secundaria a colestasis','Hipercolesterolemia familiar homocigota','Cirrosis biliar primaria'],
  obj:'Reconocer la hipercolesterolemia secundaria a colestasis y la vía biliar de eliminación del colesterol.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías EASL sobre enfermedades hepáticas colestásicas.'
},
'MIR-2021-M50': {
  esp:'Medicina Interna', tema:'Endocrinología', sub:'Antidiabéticos con beneficio cardiovascular',
  clave:'Diabético con CARDIOPATÍA ISQUÉMICA: el fármaco a añadir es un inhibidor de SGLT2, empagliflozina.',
  exp:'Cuando un paciente con diabetes tipo 2 tiene *enfermedad cardiovascular establecida*, la elección del segundo fármaco ya no depende solo de cuánto baje la glicada, sino de qué familia ha demostrado *reducir eventos y mortalidad*. Los *inhibidores de SGLT2* —empagliflozina, dapagliflozina, canagliflozina— han demostrado en ensayos como el EMPA-REG OUTCOME una reducción de la mortalidad cardiovascular, de las hospitalizaciones por insuficiencia cardiaca y de la progresión de la enfermedad renal, y por eso son de elección en este perfil junto con los *agonistas de GLP-1*. Además aportan pérdida de peso y descenso tensional, útiles aquí con un índice de masa corporal de 27 y una tensión de 151/93. Igual de importante es lo que se *evita*: la *glipizida* es una sulfonilurea, con riesgo de hipoglucemia y ganancia de peso y sin beneficio cardiovascular; la *acarbosa* tiene potencia escasa y mala tolerancia digestiva; y la *sitagliptina*, aunque segura, es *neutra* en eventos cardiovasculares. El antecedente de pancreatitis biliar, por su parte, es la razón por la que aquí se prefiere el SGLT2 a un agonista de GLP-1.',
  no:{1:'La glipizida es una sulfonilurea: produce hipoglucemias, ganancia de peso y carece de beneficio cardiovascular.',2:'La acarbosa tiene potencia escasa y mala tolerancia digestiva, y tampoco aporta beneficio en eventos.',3:'La sitagliptina es segura pero neutra en resultados cardiovasculares: no aporta la protección que este paciente necesita.'},
  trampa:'Se elige el fármaco que más baje la glicada. En el diabético con enfermedad cardiovascular lo que decide es el beneficio demostrado en eventos.',
  dx:[],
  obj:'Elegir el antidiabético según el beneficio cardiovascular demostrado.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con los estándares de la ADA y guías ESC sobre diabetes.'
},
'MIR-2021-M51': {
  esp:'Medicina Interna', tema:'Endocrinología', sub:'Gastroparesia diabética',
  clave:'Gastroparesia diabética: hace falta un PROCINÉTICO. La metoclopramida es el fármaco indicado.',
  exp:'La gastroparesia diabética es una complicación de la *neuropatía autonómica* de larga evolución —esta paciente lleva cuarenta años con diabetes tipo 1— y consiste en un *retraso del vaciamiento gástrico* sin obstrucción mecánica, que produce náuseas, saciedad precoz, distensión y plenitud posprandial, además de dificultar mucho el control glucémico porque desacopla la absorción de los alimentos de la acción de la insulina. Como el problema es *motor*, el tratamiento necesita un fármaco *procinético*, y la *metoclopramida* —antagonista dopaminérgico D2 con efecto colinérgico— acelera el vaciamiento y además tiene acción antiemética central. Su limitación es que no debe usarse de forma prolongada por el riesgo de *discinesia tardía* y de síntomas extrapiramidales, de modo que se emplea en ciclos cortos y a la dosis mínima eficaz; la domperidona es una alternativa con menos efectos centrales. A ello se suman medidas dietéticas: comidas pequeñas y frecuentes, pobres en grasa y en fibra, y optimizar el control glucémico, porque la hiperglucemia aguda enlentece aún más el vaciamiento.',
  no:{0:'El lansoprazol reduce el ácido pero no acelera el vaciamiento gástrico: no trata el problema motor.',1:'El ondansetrón es antiemético puro y carece de efecto procinético.',2:'La loperamida es antidiarreico y ENLENTECE la motilidad: agravaría el cuadro.'},
  trampa:'Se trata la náusea con un antiemético. Aquí la náusea es un síntoma del vaciamiento lento, y lo que hay que corregir es la motilidad.',
  dx:['Gastroparesia diabética','Obstrucción pilórica','Dispepsia funcional'],
  obj:'Tratar la gastroparesia diabética con un procinético y conocer sus limitaciones.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías del American College of Gastroenterology sobre gastroparesia.'
},
'MIR-2021-M74': {
  esp:'Medicina Interna', tema:'Endocrinología', sub:'Menopausia y terapia hormonal',
  clave:'FSH de 95 con estradiol indetectable: menopausia. Sofocos que alteran el sueño: estrógenos TRANSDÉRMICOS, con el DIU dando la protección endometrial.',
  exp:'El perfil hormonal es concluyente: *FSH muy elevada* con *estradiol indetectable* indica *fallo ovárico*, y la función tiroidea es normal, de modo que los sofocos y las palpitaciones no son de origen tiroideo. La paciente tiene síntomas vasomotores que le impiden descansar, lo que constituye la indicación clásica de *terapia hormonal*. La elección de la respuesta tiene dos matices que hay que ver. El primero: se prefiere la *vía transdérmica* frente a la oral porque evita el primer paso hepático y, con ello, *no aumenta el riesgo tromboembólico* ni eleva los triglicéridos, siendo especialmente recomendable a partir de los 40 y en cualquier paciente con factores de riesgo. El segundo: normalmente el estrógeno debe acompañarse de un *gestágeno* para proteger el endometrio de la hiperplasia, pero esta paciente ya es portadora de un *DIU de levonorgestrel*, que aporta precisamente esa protección, de modo que basta con añadir el estrógeno. Los estrógenos vaginales, por su parte, solo tratan la atrofia genitourinaria y no alcanzan concentración sistémica suficiente para los sofocos.',
  no:{0:'Las benzodiacepinas tratarían el insomnio sin corregir la causa, y no están indicadas como primera línea en la menopausia.',1:'Los estrógenos vaginales actúan localmente sobre la atrofia genital y no alivian los sofocos.',2:'La vía oral aumenta el riesgo tromboembólico frente a la transdérmica, y el gestágeno oral es innecesario porque el DIU ya protege el endometrio.'},
  trampa:'Se añade un gestágeno por rutina. El DIU de levonorgestrel ya cumple esa función, y sumar otro solo añade efectos adversos.',
  dx:['Menopausia','Hipertiroidismo','Trastorno de ansiedad'],
  obj:'Indicar terapia hormonal transdérmica en la menopausia sintomática y valorar la protección endometrial.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con recomendaciones de la Asociación Española para el Estudio de la Menopausia.'
},

/* ==================== INFECTOLOGÍA E INMUNOLOGÍA ==================== */
'MIR-2021-M175': {
  esp:'Medicina Interna', tema:'Infectología', sub:'Infección tuberculosa latente',
  clave:'Mantoux positivo con radiografía normal y sin síntomas: infección LATENTE. Con acenocumarol se evita la rifampicina: isoniacida nueve meses.',
  exp:'Hay que separar dos situaciones. El paciente está *asintomático*, sin fiebre ni tos, y con *radiografía de tórax normal*: no tiene enfermedad tuberculosa, tiene una *infección tuberculosa latente* tras un contacto reciente, y el Mantoux de 12 mm lo confirma. Eso se trata para evitar que progrese, y las pautas posibles son varias: isoniacida sola durante 6 a 9 meses, rifampicina 4 meses, isoniacida más rifampicina 3 meses, o isoniacida más rifapentina semanal 3 meses. La elección aquí la decide una *interacción*: el paciente toma *acenocumarol*, y la *rifampicina* es un potentísimo inductor del citocromo P450 que aceleraría su metabolismo, hundiendo el INR y exponiéndolo a una nueva trombosis, con un reajuste de dosis muy difícil de manejar. Por eso se elige la pauta *sin rifamicinas*: *isoniacida durante nueve meses*, añadiendo piridoxina para prevenir la neuropatía y vigilando las transaminasas.',
  no:{1:'La rifampicina induce el citocromo P450 y desestabilizaría gravemente la anticoagulación con acenocumarol.',2:'También contiene rifampicina, con el mismo problema de interacción.',3:'La rifapentina es otra rifamicina y comparte exactamente el mismo efecto inductor.'},
  trampa:'Se elige la pauta más corta por comodidad. Las tres pautas cortas llevan rifamicina, y este paciente está anticoagulado.',
  dx:['Infección tuberculosa latente','Tuberculosis activa','Reacción cruzada por BCG'],
  obj:'Elegir la pauta de tratamiento de la infección latente evitando interacciones con la anticoagulación.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías de la OMS y de los CDC sobre tuberculosis latente.'
},
'MIR-2021-M178': {
  esp:'Medicina Interna', tema:'Neumología', sub:'Absceso pulmonar',
  clave:'El metronidazol en monoterapia es el MENOS eficaz en el absceso pulmonar: no cubre estreptococos microaerófilos.',
  exp:'El caso vuelve a ser un *absceso pulmonar por aspiración* en un paciente con alcoholismo y mala higiene bucal, con una cavidad de 4 cm y nivel hidroaéreo en un segmento declive, el superior del lóbulo inferior derecho. La flora responsable es *polimicrobiana* y procede de la orofaringe: anaerobios estrictos —Peptostreptococcus, Prevotella, Fusobacterium, Bacteroides— junto con *estreptococos microaerófilos y del grupo viridans*. Y ahí está la clave de la pregunta: el *metronidazol* es excelente frente a los anaerobios estrictos pero *no cubre los estreptococos*, de modo que en monoterapia fracasa en torno a la mitad de los casos, un dato clásico bien documentado. Las otras tres opciones sí son válidas: la *clindamicina* es el tratamiento de referencia histórico, la *amoxicilina-clavulánico* combina el betalactámico con el inhibidor y cubre todo el espectro, y el *moxifloxacino* es una quinolona respiratoria con buena actividad anaerobia. El tratamiento debe prolongarse semanas, hasta la resolución radiológica.',
  no:{1:'La clindamicina cubre anaerobios y estreptococos y es un tratamiento clásico del absceso pulmonar.',2:'La amoxicilina-clavulánico es hoy la opción más habitual y cubre todo el espectro orofaríngeo.',3:'El moxifloxacino tiene buena actividad frente a anaerobios y estreptococos, y es alternativa válida por vía oral.'},
  trampa:'Se identifica anaerobios con metronidazol de forma refleja. En el pulmón esa ecuación falla, y por eso se pregunta.',
  dx:['Absceso pulmonar por aspiración','Tuberculosis cavitada','Neoplasia cavitada'],
  obj:'Conocer el fallo del metronidazol en monoterapia frente a la flora orofaríngea aspirada.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con Mandell, Enfermedades Infecciosas.'
},
'MIR-2021-M179': {
  esp:'Medicina Interna', tema:'Dermatología', sub:'Leishmaniasis cutánea',
  clave:'Placa que crece lentamente y se ulcera tras una picadura, en zona mediterránea: leishmaniasis cutánea. Antimoniato intralesional.',
  exp:'El cuadro reúne todos los rasgos del *botón de Oriente*: una lesión *única*, en zona *expuesta* como la mejilla, aparecida tras una *picadura de insecto* —el flebótomo—, que crece de forma *lenta e indolora* durante semanas o meses hasta ulcerarse y cubrirse de una costra adherida, con escasas molestias. La *cuenca mediterránea*, y Valencia en concreto, es zona endémica de *Leishmania infantum*, y la *inmunosupresión* por adalimumab —un anti-TNF— favorece tanto la infección como una evolución tórpida, ya que el control de la leishmania depende de la inmunidad celular mediada por TNF e interferón gamma. El diagnóstico se confirma con frotis, biopsia con PCR o cultivo. El tratamiento de la forma *cutánea localizada* en un paciente con buen estado general es *local*, con *antimoniato de meglumina intralesional*, que consigue altas tasas de curación evitando la toxicidad cardiaca, pancreática y hepática del tratamiento sistémico; este último se reserva para las formas mucocutáneas, diseminadas o viscerales, donde se usa anfotericina B liposomal.',
  no:{0:'La isotretinoína trata el acné y otras dermatosis foliculares, no una infección parasitaria.',2:'Los corticoides sistémicos empeorarían la infección al deprimir aún más la inmunidad celular.',3:'La amoxicilina no tiene actividad antiparasitaria; la evolución lenta e indolora tampoco sugiere una infección bacteriana.'},
  trampa:'Se trata como una úlcera sobreinfectada. La evolución de meses tras una picadura, en zona endémica y con anti-TNF, es leishmaniasis mientras no se pruebe lo contrario.',
  dx:['Leishmaniasis cutánea','Carcinoma basocelular','Piodermitis','Micobacteriosis atípica'],
  obj:'Reconocer la leishmaniasis cutánea y su tratamiento local.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías de la OMS sobre leishmaniasis.'
},
'MIR-2021-M177': {
  esp:'Medicina Interna', tema:'Infectología', sub:'COVID-19 grave',
  clave:'COVID que progresa pese a dexametasona, con PCR y ferritina altas y necesidad creciente de oxígeno: añadir TOCILIZUMAB.',
  exp:'La neumonía grave por SARS-CoV-2 tiene dos fases y la respuesta depende de en cuál se encuentre el paciente. La primera es *vírica*, y en ella actúan los antivirales. La segunda es *inflamatoria*, con una respuesta inmune desregulada mediada en buena parte por la *interleucina 6*, y en ella lo que funciona es la *inmunomodulación*. Este paciente está claramente en la segunda: al cuarto día, pese a llevar dexametasona y remdesivir, *empeora* —taquipnea de 30, necesidad de oxígeno de alto flujo, progresión radiológica— y sus marcadores inflamatorios están elevados, con *PCR de 80* y *ferritina de 823*. La indicación establecida en ese escenario es *añadir tocilizumab*, un anticuerpo anti-receptor de IL-6, que en los ensayos RECOVERY y REMAP-CAP redujo mortalidad y progresión a ventilación mecánica *sumado* a los corticoides, nunca en su lugar. Sobre los distractores: la anticoagulación plena requiere trombosis documentada o alta sospecha —un dímero D de 1.800 en plena inflamación no basta—, subir los corticoides no ha demostrado beneficio adicional, y una procalcitonina de 0,45 no justifica un carbapenémico.',
  no:{0:'La anticoagulación plena exige trombosis documentada o alta sospecha; el dímero D elevado es esperable en la inflamación.',1:'Aumentar la dosis de corticoides no ha demostrado beneficio adicional y sí más efectos adversos.',3:'Una procalcitonina de 0,45 no apoya sobreinfección bacteriana suficiente para escalar a meropenem.'},
  trampa:'Se sube el corticoide porque el paciente empeora. Lo que la evidencia respalda es añadir un bloqueo específico de IL-6, no más dexametasona.',
  dx:['Neumonía grave por SARS-CoV-2','Sobreinfección bacteriana','Tromboembolismo pulmonar'],
  obj:'Indicar tocilizumab en la COVID-19 con progresión inflamatoria pese a corticoides.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con el ensayo RECOVERY y guías de la OMS.'
},
'MIR-2021-M33': {
  esp:'Medicina Interna', tema:'Inmunología', sub:'Inmunoterapia con alérgenos',
  clave:'La inmunoterapia específica es el único tratamiento ETIOLÓGICO de la alergia, y debe mantenerse un MÍNIMO de 3 años.',
  exp:'En la rinoconjuntivitis alérgica los antihistamínicos y los corticoides nasales son tratamientos *sintomáticos*: alivian mientras se toman y no modifican el curso de la enfermedad. La *inmunoterapia específica con alérgenos* es el único tratamiento *etiológico*, porque induce *tolerancia inmunológica* frente al alérgeno responsable —con desviación de la respuesta hacia linfocitos T reguladores, producción de IgG4 bloqueante y descenso progresivo de la IgE específica—. Sus indicaciones son exactamente las del caso: alergia mediada por IgE bien documentada, con síntomas *no controlados* pese al tratamiento farmacológico correcto. Y el punto que pregunta el enunciado es la *duración*: para que el efecto sea duradero y persista tras suspenderla debe mantenerse un *mínimo de tres años*, habitualmente de tres a cinco, tanto por vía sublingual como subcutánea. Además tiene un beneficio añadido de gran valor en una paciente de 16 años: reduce el riesgo de que la rinitis evolucione a *asma* y de que aparezcan nuevas sensibilizaciones.',
  no:{1:'Un año es insuficiente: el efecto no se consolida y se pierde al suspenderla.',2:'El omalizumab es un anti-IgE indicado en asma alérgica grave y urticaria crónica, y su efecto es sintomático, no etiológico.',3:'El omalizumab tampoco induce tolerancia: al suspenderlo reaparecen los síntomas.'},
  trampa:'Se plantea la inmunoterapia como un tratamiento estacional. Es un tratamiento de años, y ahí reside su capacidad de modificar la enfermedad.',
  dx:[],
  obj:'Conocer la indicación y la duración mínima de la inmunoterapia con alérgenos.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías EAACI y el documento ARIA.'
},
'MIR-2021-M37': {
  esp:'Emergencias', tema:'Anafilaxia', sub:'Tratamiento y confirmación',
  clave:'En la anafilaxia lo primero SIEMPRE es ADRENALINA intramuscular. Y para confirmarla después se mide la TRIPTASA sérica.',
  exp:'La anafilaxia es un diagnóstico clínico y su tratamiento tiene un orden que no admite discusión: *adrenalina intramuscular* en la cara anterolateral del muslo, a dosis de 0,3 a 0,5 mg, repetible cada 5 a 15 minutos. Es el *único* fármaco que actúa sobre todos los mecanismos a la vez —vasoconstricción alfa que revierte la hipotensión y el edema, broncodilatación beta-2, inotropismo beta-1 y estabilización del mastocito—, y el retraso en administrarla es el principal factor asociado a la muerte por anafilaxia. Solo *después* vienen los tratamientos coadyuvantes: el *broncodilatador inhalado* para el broncoespasmo residual, el *antihistamínico* para la urticaria y el prurito, y los corticoides, que no actúan en la fase aguda y se usan pensando en la reacción bifásica. En cuanto a la confirmación diagnóstica *a posteriori*, la prueba es la *triptasa sérica*, un marcador de degranulación mastocitaria que se eleva a los 15-180 minutos y debe extraerse en las primeras horas, comparándola con un valor basal tomado más tarde. La proteína catiónica del eosinófilo, en cambio, es un marcador de inflamación eosinofílica, propio del asma, y no sirve aquí.',
  no:{1:'Retrasar la adrenalina poniendo antes el broncodilatador y el antihistamínico es el error que mata en la anafilaxia.',2:'Además de invertir el orden, la proteína catiónica del eosinófilo no confirma una anafilaxia.',3:'El orden de fármacos es correcto, pero el marcador que confirma la degranulación mastocitaria es la triptasa, no la proteína catiónica.'},
  trampa:'Se administran primero el antihistamínico y el corticoide por parecer más inocuos. La adrenalina es la primera, y no tiene contraindicación absoluta en la anafilaxia.',
  dx:['Anafilaxia por alimentos','Crisis asmática','Angioedema hereditario','Reacción vasovagal'],
  obj:'Ordenar el tratamiento de la anafilaxia y conocer la triptasa como marcador confirmatorio.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías de la World Allergy Organization y el documento GALAXIA.'
},
'MIR-2021-M38': {
  esp:'Medicina Interna', tema:'Inmunología', sub:'Alergia a Anisakis',
  clave:'El Anisakis se destruye por CONGELACIÓN a menos 20 grados o por cocción completa: el pescado ultracongelado comercialmente es seguro.',
  exp:'El *Anisakis simplex* es un nematodo que parasita el pescado marino y que produce dos cuadros distintos: la *anisakiasis*, por invasión de la larva viva en la pared gástrica o intestinal, y la *alergia*, mediada por IgE frente a sus antígenos. La larva se destruye con *calor* —cocinado completo por encima de 60 grados en el centro de la pieza— y con *congelación* a menos 20 grados durante al menos 24 a 48 horas, que es exactamente lo que garantiza el *pescado ultracongelado comercialmente*, sometido a congelación industrial rápida y profunda. Lo peligroso es el pescado *crudo o poco procesado*: boquerones en vinagre, ceviche, sushi, marinados, ahumados en frío, salazones ligeras y pescado poco hecho a la plancha, porque en una pieza gruesa el centro puede no alcanzar la temperatura necesaria. Conviene precisar que en pacientes con alergia demostrada algunos antígenos son *termoestables* y pueden dar síntomas incluso con la larva muerta, motivo por el cual en los casos más graves se recomienda evitar el pescado marino; pero de las cuatro opciones, la única segura es la del ultracongelado. Los crustáceos y moluscos no son huéspedes del parásito.',
  no:{0:'Es una restricción excesiva: los crustáceos, moluscos y cefalópodos no son huéspedes habituales del Anisakis.',1:'El pescado a la plancha puede no alcanzar en el centro la temperatura necesaria para destruir la larva.',3:'El marinado y el ahumado en frío NO destruyen el parásito: son precisamente las preparaciones de mayor riesgo.'},
  trampa:'Se supone que cualquier cocinado basta. El calor sirve solo si llega al centro de la pieza; la congelación industrial es la garantía más fiable.',
  dx:['Alergia a Anisakis','Anisakiasis gastrointestinal','Alergia a proteínas de pescado'],
  obj:'Conocer las medidas que destruyen el Anisakis y las preparaciones de riesgo.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con documentos de la AESAN y guías EAACI.'
},

/* ==================== REUMATOLOGÍA Y NEFROLOGÍA ==================== */
'MIR-2021-M180': {
  esp:'Medicina Interna', tema:'Reumatología', sub:'Granulomatosis con poliangeítis',
  clave:'Vía aérea SUPERIOR (costras nasales) más ÓRBITA (proptosis) más riñón: granulomatosis con poliangeítis.',
  exp:'La *granulomatosis con poliangeítis* es la única vasculitis que reúne estos tres territorios. El primero es la *vía aérea superior*: obstrucción nasal, rinorrea sanguinolenta y *costras serohemáticas* sobre mucosa eritematosa, que si progresa lleva a la perforación del tabique y a la nariz en silla de montar. El segundo es la *órbita*: el granuloma retroorbitario produce *proptosis*, dolor y diplopía, y es una manifestación muy característica que puede amenazar la visión. Y el tercero es el *riñón*, aquí en forma incipiente con *microhematuria y proteinuria*, expresión de una glomerulonefritis pauciinmune que puede volverse rápidamente progresiva si no se trata. Todo ello sobre un síndrome constitucional de tres meses con VSG muy elevada. El anticuerpo asociado es el *c-ANCA con especificidad anti-proteinasa 3*, y el tratamiento de inducción es corticoides a dosis altas más rituximab o ciclofosfamida. Reconocerla pronto importa mucho, porque suele confundirse durante meses con una sinusitis crónica rebelde.',
  no:{0:'La granulomatosis eosinofílica con poliangeítis cursa con asma, rinosinusitis con pólipos y EOSINOFILIA marcada, que aquí no existe.',1:'La poliangeítis microscópica no afecta a la vía aérea superior ni forma granulomas orbitarios.',3:'La poliarteritis nudosa afecta a vasos de mediano calibre, no produce glomerulonefritis ni afectación otorrinolaringológica.'},
  trampa:'Se trata como una sinusitis crónica que no responde. Las costras nasales con proptosis y un sedimento alterado son una vasculitis, no una infección.',
  dx:['Granulomatosis con poliangeítis','Sinusitis crónica','Linfoma nasal','Sarcoidosis'],
  obj:'Reconocer la tríada otorrinolaringológica, orbitaria y renal de la granulomatosis con poliangeítis.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con la nomenclatura de Chapel Hill y recomendaciones EULAR.'
},
'MIR-2021-M181': {
  esp:'Medicina Interna', tema:'Hematología', sub:'Síndrome antifosfolípido',
  clave:'Hipoxemia con hipocapnia sugestiva de TEP y TTPA alargado con protrombina normal: anticoagulante lúpico.',
  exp:'La gasometría cuenta la primera mitad de la historia: *pO2 de 70 con pCO2 de 32* es una hipoxemia con hiperventilación compensadora, en una paciente disneica con taquicardia y *auscultación pulmonar normal*, cuadro muy sugestivo de *tromboembolismo pulmonar*. La coagulación cuenta la segunda: el *TTPA está alargado*, con una ratio de 2, mientras el *tiempo de protrombina es normal*. Esa disociación en una paciente que acaba de *trombosar* es paradójica solo en apariencia, y es la firma del *anticoagulante lúpico*: un anticuerpo antifosfolípido que interfiere con los fosfolípidos del reactivo de laboratorio y alarga la prueba *in vitro*, mientras *in vivo* favorece la trombosis. La confirmación exige demostrar el anticuerpo —anticoagulante lúpico, anticardiolipina o antibeta-2-glicoproteína I— en *dos determinaciones separadas al menos doce semanas*, y el tratamiento es anticoagulación indefinida con antagonistas de la vitamina K, evitando los anticoagulantes directos en los perfiles de alto riesgo.',
  no:{1:'El factor V Leiden es la trombofilia hereditaria más frecuente, pero NO altera el TTPA.',2:'La hemofilia alarga el TTPA pero produce hemorragias, no trombosis, y afecta a varones.',3:'La pericarditis aguda cursa con dolor torácico que mejora al inclinarse hacia delante y roce pericárdico, no con hipoxemia.'},
  trampa:'Un TTPA alargado se interpreta como riesgo de sangrado. Cuando coincide con una trombosis, lo que hay que pensar es justo lo contrario.',
  dx:['Síndrome antifosfolípido','Trombofilia hereditaria','Tromboembolismo pulmonar','Lupus'],
  obj:'Sospechar el anticoagulante lúpico ante trombosis con TTPA alargado.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con los criterios de Sídney y Harrison, 21.ª ed.'
},
'MIR-2021-M183': {
  esp:'Medicina Interna', tema:'Reumatología', sub:'Polimialgia reumática',
  clave:'Dolor y rigidez de cinturas en una mujer mayor de 50 con VSG alta: polimialgia reumática. Corticoides a dosis bajas.',
  exp:'La polimialgia reumática se reconoce por un cuadro muy estereotipado: paciente *mayor de 50 años*, dolor y *rigidez matutina prolongada* en cinturas *escapular y pelviana*, de forma simétrica, con dificultad para levantarse de la cama o peinarse, y *elevación de reactantes de fase aguda* —VSG y proteína C reactiva—. Es importante fijarse en dos matices que la pregunta incluye: el dolor *mejora con la movilización* a lo largo del día, que es el patrón *inflamatorio*, y en la exploración lo que hay es dolor y rigidez, no debilidad muscular real, algo que la distingue de las miopatías, en las que además la CK estaría elevada. El tratamiento es *prednisona a dosis bajas*, en torno a 12,5 a 25 mg al día, y su respuesta es tan rápida y espectacular —en 24 a 72 horas— que forma parte del diagnóstico: si no mejora, hay que replantearse todo. Y algo que nunca debe olvidarse: hasta un 15-20% asocia una *arteritis de células gigantes*, por lo que hay que preguntar siempre por cefalea, claudicación mandibular y alteraciones visuales, como el enunciado se cuida de descartar.',
  no:{0:'La artritis reumatoide afecta a pequeñas articulaciones de manos y pies de forma simétrica, con sinovitis objetivable y factor reumatoide o anti-CCP.',1:'La fibromialgia cursa con dolor difuso crónico y reactantes de fase aguda NORMALES.',3:'La espondilitis anquilosante debuta en varones jóvenes con dolor lumbar inflamatorio y sacroileítis, no a los 70 años en las cinturas.'},
  trampa:'Se confunde con fibromialgia por tratarse de dolor difuso en una mujer. La VSG elevada y la edad separan una de otra sin dificultad.',
  dx:['Polimialgia reumática','Artritis reumatoide del anciano','Fibromialgia','Miopatía inflamatoria'],
  obj:'Diagnosticar la polimialgia reumática y vigilar la arteritis de células gigantes asociada.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con los criterios ACR/EULAR de polimialgia reumática.'
},
'MIR-2021-M184': {
  esp:'Medicina Interna', tema:'Hematología', sub:'Anemia hemolítica en el lupus',
  clave:'Anemia MACROCÍTICA de instauración rápida en una paciente con lupus: el test de Coombs es lo que decide el tratamiento.',
  exp:'La pregunta pide la determinación que *decide la actuación*, y hay que leer dos datos juntos. El primero es la *velocidad*: la anemia se ha instaurado en *quince días* hasta una hemoglobina de 7,4, lo que descarta un proceso carencial lento. El segundo es el *volumen corpuscular de 108*, es decir, *macrocitosis*, que en una anemia de instalación tan rápida se explica por la salida masiva de *reticulocitos*, que son células grandes, y no por un déficit de B12 o folato. Sumado al diagnóstico de *lupus*, todo apunta a una *anemia hemolítica autoinmune*, que es una de las manifestaciones hematológicas de la enfermedad y forma parte de sus criterios clasificatorios. El *test de Coombs directo* es el que lo confirma, y su resultado cambia la conducta de inmediato: si es positivo, se inician *corticoides a dosis altas* y se avisa al banco de sangre, porque los autoanticuerpos complican las pruebas cruzadas. La haptoglobina apoyaría que hay hemólisis pero no diría si es inmune, y los ANA ya se sabe que serán positivos, porque el lupus está diagnosticado.',
  no:{0:'La haptoglobina confirmaría la hemólisis, pero no dice si el mecanismo es inmune ni indica el tratamiento.',2:'La B12 se pediría ante una macrocitosis ARREGENERATIVA de curso lento, no ante una anemia instaurada en quince días.',3:'Los ANA ya serán positivos: la paciente tiene lupus diagnosticado, así que no aportan nada nuevo.'},
  trampa:'La macrocitosis arrastra hacia el déficit de B12. En una anemia que aparece en dos semanas, el volumen alto lo dan los reticulocitos.',
  dx:['Anemia hemolítica autoinmune','Anemia de trastorno crónico','Anemia megaloblástica','Aplasia por parvovirus'],
  obj:'Interpretar la macrocitosis regenerativa y priorizar el test de Coombs.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con los criterios EULAR/ACR de lupus.'
},
'MIR-2022-M117': {
  esp:'Medicina Interna', tema:'Reumatología', sub:'Artritis reactiva',
  clave:'Conjuntivitis, dactilitis, sacroileítis y relaciones sin protección en un varón joven: artritis reactiva.',
  exp:'La artritis reactiva es una *espondiloartritis* desencadenada por una infección *a distancia*, habitualmente genitourinaria por *Chlamydia trachomatis* —que encaja con las relaciones sin protección del caso— o digestiva por Salmonella, Shigella, Yersinia o Campylobacter, y se asocia al *HLA-B27*. La tríada clásica de Reiter es *artritis, uretritis y conjuntivitis*, y aquí están dos de sus tres elementos, con inyección conjuntival bilateral y visión borrosa. A ello se suman los rasgos comunes de las espondiloartritis: *dolor lumbar inflamatorio* con *maniobras sacroilíacas positivas*, *dactilitis* —el dedo en salchicha por hinchazón difusa de todo el dedo— y afectación *asimétrica* de miembros. El antecedente familiar de psoriasis es el elemento que la pregunta pone para confundir, pero la *artritis psoriásica* exige psoriasis en el propio paciente o, al menos, no se diagnostica ante un desencadenante infeccioso tan claro. El tratamiento son AINE, infiltraciones, tratamiento antibiótico de la infección genital si persiste, y sulfasalazina o anti-TNF en las formas persistentes.',
  no:{1:'La artritis psoriásica exige psoriasis en el paciente; un antecedente familiar aislado no basta, y aquí hay un desencadenante infeccioso claro.',2:'La artritis enteropática acompaña a una enfermedad inflamatoria intestinal, que no se menciona.',3:'La espondilitis anquilosante es de curso crónico y axial predominante, sin conjuntivitis bilateral aguda ni desencadenante infeccioso.'},
  trampa:'El antecedente familiar de psoriasis desvía hacia la artritis psoriásica. Lo que manda es la infección desencadenante y la conjuntivitis.',
  dx:['Artritis reactiva','Artritis psoriásica','Artritis gonocócica','Espondilitis anquilosante'],
  obj:'Reconocer la artritis reactiva dentro del grupo de las espondiloartritis.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con los criterios ASAS y Harrison, 21.ª ed.'
},
'MIR-2022-M115': {
  esp:'Medicina Interna', tema:'Reumatología', sub:'Monoartritis aguda febril',
  clave:'Toda monoartritis aguda con fiebre se ARTROCENTESA antes de tratar: hay que descartar una artritis séptica.',
  exp:'La regla es de las pocas absolutas de la reumatología: ante una *monoartritis aguda*, sobre todo si se acompaña de *fiebre*, hay que realizar *artrocentesis* y enviar el líquido para *recuento celular, cristales, tinción de Gram y cultivo* antes de instaurar tratamiento. La razón es que la *artritis séptica* es una urgencia que destruye el cartílago en días y cuya presentación —dolor intenso, tumefacción, calor, enrojecimiento y febrícula— es *indistinguible* clínicamente de un ataque de gota. Y hay un matiz que la pregunta persigue: encontrar *cristales no descarta la infección*, porque ambas pueden coexistir, de modo que el cultivo es obligado igualmente. Sobre los distractores, además, hay un error terapéutico clásico: *nunca se inicia alopurinol durante la crisis aguda de gota*, porque los cambios bruscos de uricemia pueden prolongarla o agravarla; el hipouricemiante se introduce cuando el ataque ha cedido, y siempre con profilaxis con colchicina. El antecedente de hiperuricemia hace probable la gota, pero probable no es suficiente cuando lo que está en juego es una articulación.',
  no:{1:'Tratar como gota sin artrocentesis expone a pasar por alto una artritis séptica, que destruye la articulación en días.',2:'Además del error de no puncionar, el alopurinol NO debe iniciarse durante la crisis aguda.',3:'Es una escopeta de perdigones: trata todo a la vez sin diagnosticar nada, y repite el error del alopurinol en fase aguda.'},
  trampa:'Se da por hecha la gota porque hay hiperuricemia conocida. La hiperuricemia es frecuentísima y no protege de una infección articular.',
  dx:['Artritis séptica','Gota','Artritis por pirofosfato','Artritis reactiva'],
  obj:'Realizar artrocentesis en toda monoartritis aguda febril antes de tratar.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con guías EULAR sobre artritis séptica y gota.'
},
'MIR-2022-M138': {
  esp:'Medicina Interna', tema:'Nefrología', sub:'Enfermedad renal crónica avanzada',
  clave:'Riñones PEQUEÑOS, PTH de 500 y anemia: la enfermedad es CRÓNICA. Sin albuminuria y con diuresis conservada: tubulointersticial.',
  exp:'Hay que resolver dos preguntas. La primera es si el fracaso renal es agudo o crónico, y tres datos dicen que es *crónico*: los *riñones están reducidos de tamaño*, hay *anemia* por déficit de eritropoyetina y la *PTH está en 500*, es decir, un hiperparatiroidismo secundario que tarda meses o años en establecerse. La segunda es de qué tipo, y ahí decide la *ausencia de albuminuria* junto con la *diuresis conservada*: las enfermedades *glomerulares* —incluida la nefropatía diabética— cursan siempre con proteinuria significativa, mientras que las *tubulointersticiales crónicas* dañan primero el túbulo y el intersticio, produciendo pérdida de la capacidad de concentrar —de ahí la poliuria y la diuresis conservada incluso con creatinina de 10— con proteinuria escasa o ausente. Sus causas habituales son los analgésicos, el litio, las uropatías obstructivas, el reflujo, las nefropatías hereditarias y las tubulopatías. El diagnóstico es tardío precisamente porque el paciente orina bien y no tiene edemas: se presenta ya en situación de uremia, como aquí.',
  no:{0:'La poliquistosis daría riñones AUMENTADOS de tamaño y llenos de quistes en la ecografía.',1:'Una glomerulonefritis rápidamente evolutiva es aguda: los riñones tendrían tamaño normal y habría proteinuria y hematuria marcadas.',3:'La nefropatía diabética cursa siempre con albuminuria, y el enunciado señala expresamente que está ausente.'},
  trampa:'Se busca la causa glomerular por costumbre. La ausencia de albuminuria con riñones pequeños es la firma de lo tubulointersticial.',
  dx:['Nefropatía tubulointersticial crónica','Nefropatía diabética','Nefroangioesclerosis','Uropatía obstructiva'],
  obj:'Distinguir el fracaso renal crónico tubulointersticial del glomerular por la proteinuria y el tamaño renal.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con guías KDIGO y Harrison, 21.ª ed.'
},
'MIR-2022-M139': {
  esp:'Medicina Interna', tema:'Nefrología', sub:'Enfermedad por anticuerpos anti-MBG',
  clave:'Glomerulonefritis con SEMILUNAS más hemorragia alveolar: síndrome de Goodpasture. Se piden anticuerpos anti-membrana basal glomerular.',
  exp:'La biopsia ya ha dado el patrón —*glomerulonefritis difusa con semilunas*, es decir, una glomerulonefritis rápidamente progresiva— y lo que la pregunta busca es la *etiología*. La combinación de esa lesión renal con *hemorragia alveolar* —disnea de tres semanas y *crepitantes finos diseminados*— configura un *síndrome renopulmonar*, y de sus tres causas principales solo una se confirma con el anticuerpo propuesto: la *enfermedad por anticuerpos antimembrana basal glomerular* o *síndrome de Goodpasture*, en la que autoanticuerpos dirigidos contra el *colágeno tipo IV, cadena alfa-3*, atacan a la vez la membrana basal del glomérulo y la del alvéolo, que comparten ese antígeno. En la inmunofluorescencia se ve el depósito *lineal* característico. Es una urgencia porque destruye el riñón en días: el tratamiento combina *plasmaféresis* para retirar el anticuerpo con corticoides y ciclofosfamida. Las otras opciones apuntan a causas que no encajan: complemento bajo para postinfecciosa o lupus, ASLO para postestreptocócica, y E. coli O157:H7 para síndrome hemolítico urémico.',
  no:{0:'El complemento bajo orientaría a glomerulonefritis postinfecciosa, lupus o membranoproliferativa, que no explican esta hemorragia alveolar.',2:'Los ASLO indicarían infección estreptocócica previa, que produce un síndrome nefrítico sin afectación pulmonar.',3:'El E. coli O157:H7 causa síndrome hemolítico urémico, con microangiopatía y diarrea sanguinolenta, no semilunas ni hemoptisis.'},
  trampa:'Se piden ANCA por ser lo más frecuente en las glomerulonefritis con semilunas. La opción que la pregunta ofrece es la anti-MBG, y con hemorragia alveolar encaja perfectamente.',
  dx:['Enfermedad por anti-MBG','Vasculitis ANCA','Nefritis lúpica','Glomerulonefritis postinfecciosa'],
  obj:'Orientar la glomerulonefritis rápidamente progresiva según el perfil serológico.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con guías KDIGO de glomerulonefritis.'
},
'MIR-2022-M142': {
  esp:'Medicina Interna', tema:'Hematología', sub:'Mieloma múltiple',
  clave:'Anciano con dolor óseo, anemia, HIPERCALCEMIA de 11,3 y fracaso renal, con GAP de proteínas: mieloma múltiple.',
  exp:'El caso reúne el acrónimo *CRAB*, que define el mieloma sintomático: *C* de hipercalcemia, aquí *11,3*; *R* de insuficiencia renal, con creatinina de 5,4; *A* de anemia, con hemoglobina de 8,2 normocítica; y *B* de lesiones óseas, que explican el *dolor lumbosacro rebelde a antiinflamatorios* y la pérdida de 6 kilos. Hay además un dato de laboratorio muy elocuente que suele pasarse por alto: *proteínas totales de 8,2 con albúmina de solo 3,0*, es decir, un *hiato* de más de 5 g/dL de globulinas, que es el reflejo del componente monoclonal circulante. Y otro llamativo: la *proteína C reactiva es de 0,54*, prácticamente normal, lo que aleja un proceso infeccioso como la pielonefritis pese a la leucocituria del sedimento. El fracaso renal del mieloma se debe sobre todo al *riñón de cilindros*, por precipitación tubular de cadenas ligeras, agravado por la hipercalcemia, la deshidratación y los AINE que el paciente ha estado tomando. Se confirma con proteinograma, inmunofijación, cadenas ligeras libres en suero y aspirado medular.',
  no:{0:'La nefropatía por analgésicos no explica la hipercalcemia, la anemia ni el hiato entre proteínas totales y albúmina.',2:'La pielonefritis cursaría con fiebre y con una proteína C reactiva elevada, y aquí es de 0,54.',3:'La afectación bilateral de las arterias renales no produciría hipercalcemia ni el aumento de globulinas.'},
  trampa:'La leucocituria hace pensar en infección urinaria. Con PCR normal, hipercalcemia y anemia, el sedimento es un ruido y el diagnóstico está en el proteinograma.',
  dx:['Mieloma múltiple','Metástasis óseas','Hiperparatiroidismo primario','Nefropatía por AINE'],
  obj:'Reconocer el mieloma múltiple por los criterios CRAB y el hiato de proteínas.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con los criterios del International Myeloma Working Group.'
},
'MIR-2021-M205': {
  esp:'Medicina Interna', tema:'Neurología', sub:'Accidente isquémico transitorio',
  clave:'Es FALSO que el eco-Doppler de troncos supraaórticos sea poco útil: es la primera prueba para buscar estenosis carotídea.',
  exp:'El cuadro —déficit focal de 15 minutos con recuperación completa en un varón fumador e hipertenso— es un *accidente isquémico transitorio*, y hay que entenderlo como lo que es: una *urgencia*, porque el riesgo de ictus establecido en los días siguientes es alto y se reduce mucho con un estudio y un tratamiento rápidos. La afirmación *falsa* es la que desprecia el *eco-Doppler de troncos supraaórticos*, que es precisamente la exploración *inicial de elección*: no invasiva, disponible, repetible, y capaz de cuantificar el grado de estenosis carotídea y de caracterizar la placa. El resto de enunciados son correctos: la *embolia arterioarterial* desde una placa carotídea ulcerada es un mecanismo típico; la *TC craneal* es necesaria para descartar hemorragia y valorar si hay lesión establecida, dado que muchos accidentes "transitorios" dejan infarto en la imagen; y la *endarterectomía* está indicada en la estenosis sintomática *mayor del 70%*, y debe realizarse precozmente, idealmente en las dos primeras semanas, porque es cuando más beneficio aporta.',
  no:{0:'Es correcto: la embolia arterioarterial desde una placa carotídea es uno de los mecanismos más frecuentes.',2:'Es correcto: la TC descarta hemorragia y valora si existe ya una lesión isquémica establecida.',3:'Es correcto: la endarterectomía se indica en la estenosis sintomática superior al 70%.'},
  trampa:'Se desprecia la ecografía por ser una prueba sencilla. En la carótida es la primera línea, y de su resultado depende que el paciente se opere.',
  dx:['Accidente isquémico transitorio','Ictus establecido','Crisis focal','Migraña con aura'],
  obj:'Estudiar con urgencia el accidente isquémico transitorio y conocer la indicación de endarterectomía.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías ESO y AHA/ASA sobre ictus.'
},
'MIR-2022-M118': {
  esp:'Medicina Interna', tema:'Hematología', sub:'Trombosis venosa de esfuerzo',
  clave:'Trombosis axilosubclavia de esfuerzo: la flebografía NO es obligatoria. Eco-Doppler primero, angio-TC para confirmar.',
  exp:'El cuadro es un *síndrome de Paget-Schroetter* o trombosis venosa de esfuerzo: una *nadadora profesional* con edema y pesadez del brazo dominante y *circulación colateral visible* en la región pectoral, signo que indica que el drenaje profundo está ocluido y la sangre busca vías alternativas. El mecanismo es la compresión repetida de la vena subclavia en el *estrecho torácico superior*, entre la clavícula y la primera costilla, agravada por anomalías óseas —costilla cervical, callo de fractura clavicular, hipertrofia del escaleno—; de ahí que la *radiografía de tórax* sea pertinente, para buscar esas anomalías. El estudio empieza por el *eco-Doppler color*, no invasivo y de alto rendimiento, y se confirma y define la anatomía con *angio-TC* o angio-RM venosa. La afirmación *falsa* es que *deba* hacerse flebografía: es una técnica invasiva que hoy se reserva para cuando se va a realizar una intervención en el mismo acto, típicamente una trombólisis dirigida por catéter, no como confirmación obligada. El tratamiento combina anticoagulación, trombólisis precoz en casos seleccionados y descompresión quirúrgica del estrecho torácico.',
  no:{0:'Es correcto: el eco-Doppler es la primera prueba, no invasiva y de alto rendimiento.',1:'Es correcto: la radiografía busca costilla cervical u otras anomalías óseas del estrecho torácico.',2:'Es correcto: la angio-TC confirma y define la anatomía venosa.'},
  trampa:'Se considera la flebografía el patrón oro obligado. Hoy es una técnica terapéutica más que diagnóstica.',
  dx:['Síndrome de Paget-Schroetter','Trombosis por catéter','Linfedema','Compresión tumoral'],
  obj:'Ordenar el estudio de la trombosis venosa de esfuerzo del miembro superior.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con guías ACCP y Rutherford, Cirugía Vascular.'
},

/* ==================== NEUROLOGÍA, ORL Y CUIDADOS CRÍTICOS ==================== */
'MIR-2021-M197': {
  esp:'Emergencias', tema:'Traumatismo craneoencefálico', sub:'Traumatismo craneal leve',
  clave:'Glasgow 15, sin pérdida de conciencia, sin amnesia, sin vómitos y exploración normal: NINGUNA prueba de imagen.',
  exp:'El traumatismo craneal leve es motivo frecuentísimo de consulta y las reglas de decisión clínica —la *canadiense* y los *criterios de New Orleans*— existen precisamente para evitar TC innecesarias, que irradian, saturan urgencias y detectan hallazgos irrelevantes. Se indica TC cuando hay al menos uno de estos factores: *Glasgow menor de 15* a las dos horas, *sospecha de fractura abierta o deprimida*, signos de *fractura de base de cráneo* —hemotímpano, ojos de mapache, signo de Battle, otorraquia—, *dos o más episodios de vómito*, *edad igual o mayor de 65 años*, *amnesia retrógrada* de más de 30 minutos, *pérdida de conciencia*, mecanismo peligroso, *anticoagulación* o coagulopatía, o crisis convulsiva. Esta paciente de 35 años *no cumple ninguno*: Glasgow 15, sin pérdida de conciencia, sin amnesia, sin vómitos ni náuseas, con exploración neurológica normal y solo cefalea leve. Lo indicado es *observación*, analgesia y unas instrucciones claras de alarma a la familia para volver si aparecen vómitos, somnolencia, confusión o focalidad. La *radiografía simple de cráneo* está abandonada porque la fractura no predice bien la lesión intracraneal.',
  no:{0:'La TC sin contraste sería la prueba correcta SI hubiera algún criterio de riesgo, y aquí no hay ninguno.',1:'La TC con contraste no tiene ningún papel en el traumatismo craneal agudo.',3:'La radiografía simple de cráneo está abandonada: no detecta la lesión intracraneal, que es lo que importa.'},
  trampa:'Se pide TC "por si acaso" ante cualquier golpe en la cabeza. Las reglas de decisión existen para no irradiar a quien no lo necesita.',
  dx:['Traumatismo craneoencefálico leve','Conmoción cerebral','Hematoma epidural'],
  obj:'Aplicar los criterios de indicación de TC en el traumatismo craneal leve.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con la regla canadiense de TC craneal y guías NICE.'
},
'MIR-2021-M198': {
  esp:'Medicina Interna', tema:'Neumología', sub:'Síndrome de distrés respiratorio agudo',
  clave:'La causa más frecuente de distrés es INFECCIOSA: neumonía y sepsis. Y el pulmón se vuelve RÍGIDO, con P/F igual o menor de 300.',
  exp:'El síndrome de distrés respiratorio agudo se define por los *criterios de Berlín*: instauración en menos de una semana, *infiltrados bilaterales* no explicados por derrame o atelectasia, ausencia de origen cardiogénico o de sobrecarga de volumen, e *hipoxemia con cociente PaO2/FiO2 igual o inferior a 300* con al menos 5 de PEEP, lo que además lo gradúa en leve, moderado —por debajo de 200— y grave —por debajo de 100—. La afirmación correcta es la etiológica: las causas *infecciosas*, con la *neumonía* y la *sepsis* a la cabeza, son las más frecuentes, seguidas de la aspiración, el traumatismo, la pancreatitis y la transfusión masiva. Los otros enunciados permiten repasar la fisiopatología: la fase *exudativa*, con daño alveolar difuso, edema rico en proteínas y membranas hialinas, ocupa la *primera semana*, y solo después llega la proliferativa y, en algunos casos, la fibrótica. Y la *distensibilidad está muy DISMINUIDA*: el pulmón se vuelve rígido y pequeño —el llamado *baby lung*—, razón por la cual se ventila con *volúmenes bajos*, de 6 mL/kg de peso ideal, para no lesionarlo más.',
  no:{1:'La fase de los primeros siete días es la EXUDATIVA; la proliferativa viene después.',2:'La distensibilidad está muy DISMINUIDA: el pulmón se vuelve rígido, y de ahí la ventilación protectora.',3:'Por definición el cociente PaO2/FiO2 es igual o INFERIOR a 300; por encima no hay distrés.'},
  trampa:'Se piensa que un pulmón encharcado es más distensible. Ocurre lo contrario: el edema y el colapso alveolar lo endurecen.',
  dx:['Síndrome de distrés respiratorio agudo','Edema agudo de pulmón cardiogénico','Neumonía bilateral'],
  obj:'Conocer los criterios de Berlín, la fisiopatología y las causas del distrés respiratorio.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con la definición de Berlín y guías ATS/ESICM.'
},
'MIR-2022-M106': {
  esp:'Medicina Interna', tema:'Neumología', sub:'Decúbito prono en el distrés',
  clave:'El prono se indica con PaO2/FiO2 por debajo de 150, no de 300. Ese es el enunciado incorrecto.',
  exp:'El *decúbito prono* mejora la oxigenación por varios mecanismos: homogeneiza la distribución de la ventilación, recluta las zonas dorsales que estaban colapsadas por el peso del propio pulmón y del corazón, mejora la relación *ventilación/perfusión* y reduce la sobredistensión de las zonas ventrales, disminuyendo así la lesión inducida por el respirador. El ensayo *PROSEVA* demostró que aplicado *precozmente* y en sesiones *prolongadas*, de al menos 16 horas, reduce la *mortalidad* en el distrés *moderado-grave*, definido por un cociente *PaO2/FiO2 inferior a 150*. Ese es el umbral, y por eso la afirmación que habla de 300 es la incorrecta: 300 es el límite que *define* el distrés, no el que indica el prono. Los otros tres enunciados son ciertos: el objetivo es mejorar el cociente de oxigenación; la maniobra exige *personal entrenado* y coordinado para evitar extubaciones accidentales, pérdida de accesos, lesiones por presión y lesiones oculares o del plexo braquial; y requiere *sedación profunda*, a menudo con relajación neuromuscular.',
  no:{0:'Es correcto: el objetivo directo es mejorar el cociente PaO2/FiO2.',1:'Es correcto: la maniobra requiere un equipo entrenado por el riesgo de complicaciones.',3:'Es correcto: el prono en ventilación invasiva exige sedación profunda y con frecuencia relajación.'},
  trampa:'Se confunde el umbral que DEFINE el distrés, que es 300, con el que indica el prono, que es 150.',
  dx:[],
  obj:'Conocer la indicación y el fundamento del decúbito prono en el distrés respiratorio.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con el ensayo PROSEVA y guías ATS/ESICM.'
},
'MIR-2022-M105': {
  esp:'Farmacología', tema:'Farmacología', sub:'Secuencia rápida de intubación',
  clave:'La quetiapina es un antipsicótico ORAL: no tiene ningún papel en la intubación. Los inductores son etomidato, propofol o ketamina.',
  exp:'La *secuencia rápida de intubación* combina tres tipos de fármaco, y conocerlos permite descartar el intruso de un vistazo. El *hipnótico o inductor* produce inconsciencia en segundos: *etomidato*, muy usado por su estabilidad hemodinámica —a costa de una supresión suprarrenal transitoria—, propofol o ketamina. El *relajante muscular* facilita la laringoscopia: *rocuronio*, de acción rápida, o succinilcolina. Y el *analgésico opioide*, típicamente el *fentanilo*, atenúa la respuesta simpática a la laringoscopia, con el consiguiente pico hipertensivo y taquicárdico. La *quetiapina*, en cambio, es un *antipsicótico atípico de administración oral*, con inicio de acción de horas y sin presentación intravenosa: no induce anestesia ni tiene lugar alguno en este contexto. El caso añade además un detalle coherente: la ausencia de respuesta a *naloxona y flumazenilo* descarta opiáceos y benzodiacepinas como causa del coma tóxico, de modo que hay que asegurar la vía aérea y continuar el estudio.',
  no:{1:'El rocuronio es un relajante neuromuscular no despolarizante de acción rápida, estándar en la secuencia rápida.',2:'El etomidato es un inductor hipnótico de elección por su estabilidad hemodinámica.',3:'El fentanilo atenúa la respuesta simpática a la laringoscopia y forma parte habitual de la secuencia.'},
  trampa:'Se busca la contraindicación más sutil. Aquí basta con reconocer que uno de los cuatro fármacos ni siquiera existe en forma intravenosa.',
  dx:[],
  obj:'Identificar los fármacos de la secuencia rápida de intubación.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con Miller, Anestesia.'
},
'MIR-2022-M112': {
  esp:'Medicina Interna', tema:'Neurología', sub:'Polineuropatía del enfermo crítico',
  clave:'Tetraparesia con hiporreflexia tras una semana de UCI: polineuromiopatía del enfermo crítico. Rehabilitación intensiva, no corticoides.',
  exp:'La *polineuropatía y miopatía del enfermo crítico* es una complicación muy frecuente en pacientes con ventilación mecánica prolongada, sepsis, fallo multiorgánico, hiperglucemia, corticoides y relajantes neuromusculares —factores que en un paciente con COVID grave se acumulan casi todos—. Se manifiesta exactamente como aquí: *debilidad simétrica de las cuatro extremidades*, de predominio proximal, con *hiporreflexia* y, muy característicamente, *dificultad para el destete* del respirador, porque la debilidad afecta también al diafragma y a la musculatura intercostal. El diagnóstico diferencial con el *Guillain-Barré* se resuelve por el contexto —aquí la debilidad aparece *durante* el ingreso en UCI y no lo precede— y, si hiciera falta, por el electromiograma, que muestra un patrón axonal, y por el líquido cefalorraquídeo, que es normal en lugar de mostrar disociación albuminocitológica. El tratamiento no es farmacológico: los *corticoides son un factor de riesgo* y empeorarían el cuadro; lo que funciona es la *rehabilitación motora y respiratoria precoz e intensiva*, junto con el control glucémico y la reducción de sedación y relajantes.',
  no:{0:'El Guillain-Barré precede al ingreso y suele ser la causa del fallo respiratorio, no una complicación aparecida en la UCI.',1:'El síndrome postCOVID es un diagnóstico posterior al alta y no explica una tetraparesia con hiporreflexia establecida en UCI.',2:'Los corticoides son un factor de riesgo de esta miopatía: administrarlos la agravaría.'},
  trampa:'Se piensa en Guillain-Barré por la hiporreflexia. La cronología manda: aquí la debilidad aparece después de una semana de ventilación, no antes.',
  dx:['Polineuromiopatía del enfermo crítico','Síndrome de Guillain-Barré','Mielopatía','Miastenia'],
  obj:'Reconocer la debilidad adquirida en la UCI y tratarla con rehabilitación precoz.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con guías ATS sobre debilidad adquirida en el paciente crítico.'
},
'MIR-2022-M101': {
  esp:'Medicina Interna', tema:'Neurología', sub:'Ictus isquémico agudo',
  clave:'Trombo DISTAL (M3-M4) dentro de la ventana: fibrinólisis intravenosa. La trombectomía es para oclusiones de gran vaso proximal.',
  exp:'La decisión se toma cruzando tres variables. La *ventana temporal* es de *una hora*, muy dentro del plazo de 4,5 horas de la fibrinólisis intravenosa. La *viabilidad del tejido* es favorable: la TC de perfusión muestra un *defecto de flujo sin afectación en los mapas de volumen*, es decir, hay *penumbra isquémica* recuperable y todavía no hay núcleo infartado establecido. Y la *localización del trombo* es la que decide entre las dos terapias: está en los segmentos *distales M3-M4* de la cerebral media, ramas de pequeño calibre a las que el catéter *no puede llegar de forma segura y eficaz*. La *trombectomía mecánica* está indicada en la oclusión de *gran vaso proximal* —carótida intracraneal, M1 y algunos M2, o basilar—, donde ha demostrado un beneficio enorme. Para un trombo distal como este, el tratamiento indicado es la *fibrinólisis intravenosa con alteplasa*. La anticoagulación con heparina, por su parte, no tiene papel en la fase aguda del ictus isquémico.',
  no:{0:'La trombectomía se indica en oclusiones de gran vaso proximal; los segmentos M3-M4 no son accesibles de forma eficaz.',2:'Plantear la trombectomía de rescate en un trombo distal no está indicado: no es la localización adecuada.',3:'La heparina sódica no tiene indicación en la fase aguda del ictus isquémico y aumenta el riesgo hemorrágico.'},
  trampa:'Se elige la trombectomía por ser la técnica más moderna y potente. Su indicación depende de dónde esté el trombo, no de su modernidad.',
  dx:['Ictus isquémico de rama distal','Accidente isquémico transitorio','Crisis focal'],
  obj:'Elegir entre fibrinólisis y trombectomía según la localización del trombo.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con guías ESO y AHA/ASA sobre ictus isquémico.'
},
'MIR-2022-M104': {
  esp:'Medicina Interna', tema:'Neurología', sub:'Epilepsia mioclónica juvenil',
  clave:'La epilepsia mioclónica juvenil SÍ se trata desde la primera crisis: es un síndrome epiléptico definido, no una crisis aislada.',
  exp:'El diagnóstico está construido con tres piezas que hay que saber reconocer. Las *mioclonías matutinas*, esas sacudidas de los brazos al despertar que hacen soltar la taza y que los pacientes casi nunca consultan porque no las consideran una enfermedad; la *crisis tónico-clónica generalizada* desencadenada por *privación de sueño*, aquí en época de exámenes; y un electroencefalograma con *descargas de punta y polipunta-onda generalizadas*. Eso define una *epilepsia mioclónica juvenil*, un síndrome epiléptico *genético generalizado* propio de la adolescencia. Y ahí está la clave de la afirmación incorrecta: la regla general de no tratar una *primera crisis aislada* no se aplica cuando ya existe un *síndrome epiléptico establecido*, y este paciente no ha tenido una crisis aislada sino mioclonías previas más una tónico-clónica, con un electroencefalograma diagnóstico y un riesgo de recurrencia muy alto. Por eso *sí se trata*, clásicamente con *valproato* —evitándolo en mujeres en edad fértil por su teratogenicidad, donde se prefiere levetiracetam o lamotrigina—, junto con higiene de sueño y evitar el alcohol. La resonancia, en efecto, será normal, porque es una epilepsia genética sin lesión estructural.',
  no:{0:'Es correcto: al ser una epilepsia genética generalizada, la resonancia craneal suele ser normal.',2:'Es correcto: mioclonías matutinas más crisis generalizada con polipunta-onda definen la epilepsia mioclónica juvenil.',3:'Es correcto: el valproato es el fármaco clásico de elección, con las precauciones conocidas en mujeres en edad fértil.'},
  trampa:'Se aplica la norma de no tratar la primera crisis. Aquí no es la primera manifestación: las mioclonías llevaban tiempo y nadie las había preguntado.',
  dx:['Epilepsia mioclónica juvenil','Crisis sintomática aguda','Epilepsia focal secundariamente generalizada'],
  obj:'Reconocer la epilepsia mioclónica juvenil y su indicación de tratamiento desde el diagnóstico.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con la clasificación ILAE y guías NICE sobre epilepsia.'
},
'MIR-2021-M88': {
  esp:'Ciencias Básicas', tema:'Genética', sub:'Fenómeno de anticipación',
  clave:'La anticipación aparece en las enfermedades por EXPANSIÓN DE TRIPLETES. De la lista, la distrofia miotónica de Steinert.',
  exp:'El *fenómeno de anticipación* consiste en que la enfermedad se manifiesta *antes y de forma más grave* en cada generación sucesiva, y su base molecular es la *inestabilidad de una repetición de tripletes*, que tiende a *expandirse* al transmitirse, sobre todo por una de las dos líneas parentales. Las enfermedades que lo presentan forman un grupo reconocible: la *distrofia miotónica de Steinert*, por expansión CTG en el gen DMPK, con anticipación muy marcada por vía *materna* hasta el punto de que la forma congénita procede casi siempre de madres afectas; la *enfermedad de Huntington*, con expansión CAG y anticipación de predominio *paterno*; las *ataxias espinocerebelosas*; y el *X frágil*. La distrofia miotónica se reconoce clínicamente por la miotonía —dificultad para relajar la mano tras un apretón—, la debilidad distal y facial, las cataratas, la calvicie frontal, los trastornos de conducción cardiaca y la afectación endocrina. Las otras opciones tienen mecanismos distintos: la atrofia muscular espinal se debe a deleciones del gen SMN1, la distrofia de Duchenne a deleciones o mutaciones de la distrofina ligadas al X, y la enfermedad de Parkinson es en su inmensa mayoría esporádica y multifactorial.',
  no:{0:'La atrofia muscular espinal se debe a deleciones del gen SMN1, sin expansión de tripletes ni anticipación.',1:'La distrofia de Duchenne se debe a mutaciones del gen de la distrofina ligado al X, sin anticipación.',2:'La enfermedad de Parkinson es mayoritariamente esporádica y multifactorial.'},
  trampa:'Se busca la enfermedad neuromuscular más grave. Lo que define la respuesta es el mecanismo molecular, no la gravedad.',
  dx:[],
  obj:'Relacionar el fenómeno de anticipación con las expansiones de tripletes.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con Thompson y Thompson, Genética en Medicina.'
},
'MIR-2021-M94': {
  esp:'Psiquiatría', tema:'Toxicología', sub:'Delirium tremens',
  clave:'Cuadro confusional al segundo o tercer día de ingreso en un bebedor: delirium tremens. Benzodiacepinas de vida media LARGA.',
  exp:'La secuencia temporal es la que hace el diagnóstico: un paciente ingresado por otro motivo empieza a los *dos días* con nerviosismo y temblor y al *tercero* con insomnio, ansiedad intensa, desorientación temporal e incoherencia. Eso es un *síndrome de abstinencia alcohólica* que evoluciona a *delirium tremens*, cuyo pico se sitúa entre las 48 y las 96 horas desde la última ingesta. La *negación del consumo* es habitual y por eso la información de la esposa es decisiva: bebe cantidades importantes a diario desde hace años. El tratamiento son las *benzodiacepinas de vida media larga* —diazepam, clorazepato—, porque su descenso plasmático es suave y evitan las oscilaciones que reactivan los síntomas; en España se asocia clásicamente el *clometiazol*. A ello se añade siempre *tiamina parenteral antes que cualquier glucosa*, para prevenir la encefalopatía de Wernicke, más hidratación y corrección de electrolitos. Es un cuadro con mortalidad apreciable si no se trata, de modo que reconocerlo pronto importa.',
  no:{1:'Las de vida media corta obligan a dosis frecuentes y producen oscilaciones; los betabloqueantes enmascaran los signos autonómicos sin prevenir las crisis.',2:'La carbamazepina puede usarse en abstinencias leves, pero no es el tratamiento de elección del delirium tremens establecido.',3:'La clozapina es un antipsicótico con riesgo de agranulocitosis y de bajar el umbral convulsivo: nada indicado aquí.'},
  trampa:'Se etiqueta de cuadro confusional postoperatorio y se dan antipsicóticos. La cronología de 48 a 72 horas tras el ingreso obliga a pensar en abstinencia.',
  dx:['Delirium tremens','Delirium por otras causas','Encefalopatía de Wernicke','Psicosis aguda'],
  obj:'Reconocer y tratar el delirium tremens en el paciente hospitalizado.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías NICE y el DSM-5-TR.'
},
'MIR-2021-M98': {
  esp:'Medicina Interna', tema:'Neurología', sub:'Progresión del Alzheimer',
  clave:'El orden habitual es: cambios de humor, luego déficit cognitivo y finalmente pérdida de independencia funcional.',
  exp:'La enfermedad de Alzheimer tiene una progresión razonablemente predecible que conviene conocer para orientar a las familias. En una *fase prodrómica* aparecen a menudo *cambios de humor* —apatía, ánimo depresivo, irritabilidad, ansiedad y pérdida de iniciativa—, que con frecuencia se interpretan como una depresión y son motivo de consulta antes que los olvidos, exactamente como en esta paciente, a la que la familia describe "deprimida". Después se instaura el *déficit cognitivo*, comenzando por la *memoria episódica reciente* y añadiendo con el tiempo lenguaje, praxias y funciones ejecutivas. Y solo más tarde, cuando el déficit es suficientemente amplio, llega el *declive de la independencia funcional*: primero en las actividades instrumentales —manejar dinero, medicación, transporte— y finalmente en las básicas. Los *síntomas conductuales* graves, como el delirio o la agitación, y los *síntomas motores*, como la rigidez y las alteraciones de la marcha, corresponden a fases *avanzadas*, no al inicio. Un detalle más del caso, muy típico: la *anosognosia*, esa falta de conciencia del problema que hace que sea la familia quien consulta.',
  no:{0:'Los síntomas conductuales graves son propios de fases avanzadas, no anteriores al déficit cognitivo.',1:'Los síntomas motores aparecen tarde: iniciar la secuencia con ellos describe otras demencias, no el Alzheimer.',3:'Vuelve a situar los síntomas conductuales y motores al principio, que es lo característico de la demencia frontotemporal o de los parkinsonismos.'},
  trampa:'Se piensa que el Alzheimer empieza siempre por la memoria. En muchos casos lo primero que nota la familia es un cambio del ánimo o del carácter.',
  dx:['Enfermedad de Alzheimer','Depresión del anciano','Deterioro cognitivo leve','Demencia frontotemporal'],
  obj:'Conocer el orden habitual de aparición de los síntomas en el Alzheimer.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con los criterios NIA-AA y guías NICE sobre demencia.'
},
'MIR-2021-M60': {
  esp:'Medicina Interna', tema:'Otorrinolaringología', sub:'Otitis media serosa del adulto',
  clave:'Otitis serosa UNILATERAL en un adulto con adenopatía cervical: hay que explorar la NASOFARINGE para descartar un tumor.',
  exp:'La exploración describe una *otitis media serosa*: membrana timpánica *íntegra* con *líquido ambarino y burbujas* en el oído medio, e *hipoacusia de transmisión* confirmada por las pruebas acumétricas —*Rinne negativo* en el oído afecto, es decir, la conducción ósea supera a la aérea, y *Weber lateralizado al mismo oído*, que es lo que ocurre en las hipoacusias conductivas—. En el *niño* esta situación es banal y se debe a disfunción tubárica por hipertrofia adenoidea o catarros. En el *adulto*, y sobre todo si es *unilateral* y sin antecedente catarral, es una *señal de alarma*: obliga a explorar la *nasofaringe* con fibroscopia, porque una masa en la fosa de Rosenmüller puede obstruir la trompa de Eustaquio, y el *carcinoma de cavum* se presenta precisamente así, con otitis serosa unilateral y *adenopatía cervical* como primer signo, tal y como describe el enunciado. El tratamiento del derrame no sirve de nada si no se descarta antes la causa.',
  no:{0:'No hay otitis media aguda: no hay otalgia, fiebre ni abombamiento timpánico, y el líquido es ambarino, no purulento.',1:'El colesteatoma cursa con otorrea crónica fétida y perforación o retracción timpánica, y aquí la membrana está íntegra.',3:'La hipoacusia es de TRANSMISIÓN, no neurosensorial: el Rinne negativo y el Weber al oído enfermo lo demuestran.'},
  trampa:'Se trata el derrame con antibiótico o descongestionantes. En un adulto con otitis serosa unilateral y una adenopatía, lo urgente es mirar el cavum.',
  dx:['Carcinoma de cavum','Otitis media serosa por disfunción tubárica','Colesteatoma','Otoesclerosis'],
  obj:'Reconocer la otitis serosa unilateral del adulto como signo de alarma de tumor nasofaríngeo.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías de la American Academy of Otolaryngology.'
},
'MIR-2021-M65': {
  esp:'Medicina Interna', tema:'Otorrinolaringología', sub:'Complicaciones de la sinusitis',
  clave:'Sospecha de complicación supurada INTRACRANEAL: la prueba es la resonancia con GADOLINIO, no la TC.',
  exp:'La secuencia clínica es la de una *sinusitis complicada*: mejoría inicial con tratamiento y, dos semanas después, reaparición con *fiebre, cefalea intensa, náuseas y malestar general*, que son los síntomas de una complicación *endocraneal*. Las posibles son varias y todas graves: *absceso epidural o subdural*, *absceso cerebral* —clásicamente del lóbulo frontal desde el seno frontal—, *meningitis* y *trombosis del seno cavernoso o del seno sagital*. La prueba de elección es la *resonancia magnética con gadolinio*, porque tiene una sensibilidad muy superior a la TC para las colecciones extraaxiales finas, para la afectación meníngea y para la trombosis venosa, y define mejor la extensión. La *TC del macizo facial* es excelente para la anatomía ósea de los senos y sirve para planificar la cirugía, pero es insuficiente para el compromiso intracraneal, que es lo que pregunta el enunciado. Y la *punción lumbar* está *contraindicada* mientras no se descarte una lesión ocupante de espacio, por riesgo de herniación.',
  no:{0:'La TC del macizo facial valora bien el hueso y los senos, pero es insuficiente para las complicaciones intracraneales.',1:'La endoscopia nasal permite ver la fosa y tomar cultivos, pero no valora el interior del cráneo.',3:'La punción lumbar está contraindicada antes de descartar una lesión ocupante de espacio.'},
  trampa:'Se pide TC por ser lo más rápido y disponible. Cuando lo que se busca es una colección intracraneal, la resonancia con contraste es la que la ve.',
  dx:['Absceso intracraneal','Meningitis','Trombosis de seno venoso','Celulitis orbitaria'],
  obj:'Elegir la resonancia con gadolinio ante sospecha de complicación intracraneal de una sinusitis.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías EPOS sobre rinosinusitis.'
},
'MIR-2021-M68': {
  esp:'Medicina Interna', tema:'Otorrinolaringología', sub:'Vértigo posicional paroxístico benigno',
  clave:'Vértigo de SEGUNDOS con los cambios posturales y Dix-Hallpike positivo con latencia: VPPB. Maniobra de Epley del mismo lado.',
  exp:'Todos los elementos del diagnóstico están en el enunciado. La clínica es de crisis *muy breves*, de segundos, desencadenadas por *cambios de posición de la cabeza* —girarse en la cama es el desencadenante más típico—, *sin síntomas cocleares*: no hay hipoacusia, ni acúfenos, ni sensación de taponamiento, lo que descarta la enfermedad de Ménière. La exploración es normal en reposo y sin *nistagmo espontáneo*, lo que aleja una neuronitis vestibular, que cursa con vértigo continuo de días y nistagmo espontáneo unidireccional. Y la *maniobra de Dix-Hallpike derecha* reproduce el cuadro con las tres características que definen el origen *periférico* y el canal *posterior*: *latencia* breve antes de aparecer, *nistagmo torsional y vertical* agotable, y *duración inferior a un minuto*, con vértigo y náuseas. El tratamiento es una *maniobra de reposicionamiento*, la de *Epley* del *mismo lado* que resultó positivo, que devuelve los otoconios del canal semicircular al utrículo y resuelve el cuadro en la mayoría de los pacientes con una o dos sesiones. Los sedantes vestibulares no curan y dificultan la compensación.',
  no:{0:'Un vértigo central daría nistagmo sin latencia, no agotable, a menudo vertical puro, y con otros signos neurológicos.',2:'La neuronitis vestibular cursa con vértigo CONTINUO de días y nistagmo espontáneo, no con crisis de segundos posicionales.',3:'El Ménière asocia hipoacusia fluctuante, acúfeno y taponamiento, y sus crisis duran horas: aquí no hay ningún síntoma coclear.'},
  trampa:'Se receta un sedante vestibular y se manda a casa. El vértigo posicional se cura con una maniobra en la propia consulta.',
  dx:['Vértigo posicional paroxístico benigno','Neuronitis vestibular','Enfermedad de Ménière','Vértigo central'],
  obj:'Diagnosticar el VPPB con el Dix-Hallpike y tratarlo con la maniobra de Epley.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías de la American Academy of Otolaryngology sobre VPPB.'
},

/* ==================== TRAUMATOLOGÍA, DIGESTIVO Y ONCOLOGÍA ==================== */
'MIR-2021-M208': {
  esp:'Cirugía', tema:'Traumatología', sub:'Hernia discal L5-S1',
  clave:'Dolor por la cara POSTERIOR hasta el borde LATERAL del pie, reflejo AQUÍLEO abolido y no puede ponerse de puntillas: raíz S1, hernia L5-S1.',
  exp:'Las radiculopatías lumbares se identifican con tres datos que hay que emparejar sin dudar. Aquí el *territorio del dolor* recorre la cara *posterior* del muslo y la pierna hasta el *borde lateral del pie*, que es el dermatoma *S1*. El *reflejo abolido* es el *aquíleo*, que depende también de *S1*. Y la debilidad afecta a la *flexión plantar* —no puede ponerse de puntillas—, es decir, al tríceps sural, inervado igualmente por *S1*. Los tres apuntan al mismo sitio, y como la hernia posterolateral comprime la raíz que sale por debajo, la responsable es la del disco *L5-S1*. Conviene fijar la pareja contraria para no confundirse: la raíz *L5* da dolor por la cara *lateral* de la pierna hasta el *dorso del pie y el primer dedo*, debilidad para la *dorsiflexión* —no puede caminar de talones— y *no altera ningún reflejo*, ya que ni el rotuliano ni el aquíleo dependen de ella. El *Lasègue positivo a 40 grados* confirma que hay compromiso radicular y no un dolor lumbar mecánico simple.',
  no:{0:'La raíz L2 daría dolor en la cara anterior y proximal del muslo, con debilidad para la flexión de cadera.',1:'La hernia L3-L4 afecta a L4: dolor anterior de muslo y cara medial de la pierna, con reflejo ROTULIANO alterado.',2:'La hernia L4-L5 afecta a L5: dorso del pie, debilidad para la dorsiflexión y sin alteración de reflejos.'},
  trampa:'Se recuerda el dermatoma pero se olvida el reflejo. El aquíleo abolido señala S1 de forma inequívoca.',
  dx:['Hernia discal L5-S1','Hernia discal L4-L5','Estenosis de canal','Síndrome piramidal'],
  obj:'Localizar la raíz comprimida por dermatoma, reflejo y grupo muscular.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con Campbell, Cirugía Ortopédica.'
},
'MIR-2022-M114': {
  esp:'Cirugía', tema:'Traumatología', sub:'Radiculopatía L4',
  clave:'Dolor anterolateral de muslo y cara anterior de rodilla con reflejo ROTULIANO disminuido y fallo para la marcha de talones: raíz L4.',
  exp:'La exploración señala la raíz *L4*: el *dermatoma* recorre la cara *anterolateral del muslo* hasta la *cara anterior de la rodilla* y la cara medial de la pierna; el *reflejo rotuliano* depende de L4 y está *disminuido*; y la *marcha de talones*, es decir, la dorsiflexión del pie, depende del *tibial anterior*, cuya inervación es *L4-L5*, de modo que su debilidad encaja con una afectación de L4 con participación de L5. La respuesta oficial sitúa la hernia en el nivel *L4-L5*, lo que ocurre cuando la protrusión es *foraminal o extraforaminal*: en esa localización el disco comprime la raíz que *sale por ese mismo agujero*, que es la L4, en lugar de la raíz descendente L5 que comprime la hernia posterolateral clásica. Conviene tener claras las dos reglas, porque el emparejamiento habitual de examen —L3-L4 comprime L4— sigue siendo cierto para la hernia posterolateral; lo que este caso añade es que el mismo nivel discal puede dar síndromes distintos según *dónde* protruya el disco.',
  no:{0:'La raíz L2-L3 daría dolor más proximal en la cara anterior del muslo, con debilidad para la flexión de cadera y sin afectación del tibial anterior.',1:'La hernia posterolateral L3-L4 comprime L4 y explicaría el reflejo rotuliano, pero no la afectación del tibial anterior propia de L4-L5.',3:'La hernia L5-S1 afectaría a S1: cara posterior, borde lateral del pie, reflejo aquíleo y marcha de puntillas.'},
  trampa:'Se memoriza solo la pareja nivel-raíz. La localización de la hernia dentro del nivel —posterolateral o foraminal— cambia qué raíz se comprime.',
  dx:['Hernia discal L4-L5 foraminal','Hernia L3-L4','Radiculopatía L5','Neuropatía femoral'],
  obj:'Explicar por qué un mismo nivel discal puede comprimir raíces distintas según la localización de la hernia.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con Campbell, Cirugía Ortopédica.'
},
'MIR-2022-M111': {
  esp:'Cirugía', tema:'Traumatología', sub:'Estenosis de canal lumbar',
  clave:'Dolor al estar de pie y al caminar que DESAPARECE sentado, sin irradiación radicular y con Lasègue negativo: estenosis de canal.',
  exp:'La *claudicación neurógena* de la estenosis de canal lumbar tiene una firma postural inconfundible: el dolor aparece *de pie y caminando* y *desaparece al sentarse o al inclinarse hacia delante*. La explicación es mecánica: la *extensión* lumbar, que es la postura de la bipedestación, estrecha aún más el canal al plegarse el ligamento amarillo, mientras que la *flexión* lo amplía; por eso estos pacientes caminan encorvados, toleran mucho mejor la bicicleta o empujar un carro de la compra que caminar erguidos, y descansan sentados. El caso añade otros elementos coherentes: *edad avanzada*, *obesidad central* que aumenta la lordosis, dolor *difuso hacia ambos glúteos* sin seguir un dermatoma concreto, y *Lasègue negativo*, que descarta la irritación radicular de una hernia. El diagnóstico diferencial obligado es con la *claudicación vascular*, que también obliga a parar al caminar, pero en ella el alivio depende de *detenerse*, no de la postura, y hay que explorar los pulsos distales. El diagnóstico se confirma con resonancia.',
  no:{0:'Una hernia L5-S1 daría dolor irradiado a la pierna en un dermatoma definido y Lasègue positivo.',2:'Una hernia L4-L5 tampoco encaja: no hay irradiación radicular ni signos de tensión radicular.',3:'La espondilodiscitis cursa con dolor CONSTANTE, que no mejora con el reposo, con fiebre y elevación de reactantes.'},
  trampa:'Se confunde con claudicación vascular. La diferencia es qué alivia: en la vascular basta con pararse, en la neurógena hay que sentarse o flexionarse.',
  dx:['Estenosis de canal lumbar','Hernia discal','Claudicación vascular','Espondilodiscitis'],
  obj:'Reconocer la claudicación neurógena y su comportamiento postural.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con Campbell, Cirugía Ortopédica.'
},
'MIR-2022-M108': {
  esp:'Pediatría', tema:'Traumatología infantil', sub:'Cadera dolorosa febril',
  clave:'Niño con fiebre y cadera que no apoya: la primera prueba es la ECOGRAFÍA, que detecta el derrame y permite puncionarlo.',
  exp:'Un niño con *fiebre*, *rechazo del apoyo* y *limitación de la movilidad de la cadera*, con elevación de reactantes de fase aguda, tiene una *artritis séptica de cadera* mientras no se demuestre lo contrario, y esa es una de las auténticas urgencias de la traumatología infantil: la cadera es una articulación profunda, de difícil exploración, y el pus a presión puede necrosar la cabeza femoral en pocas horas. La prueba de elección inicial es la *ecografía*, por tres razones: detecta el *derrame articular* con gran sensibilidad, no irradia y no requiere sedación, y permite guiar la *artrocentesis* que dará el diagnóstico definitivo con el análisis y el cultivo del líquido. La *radiografía* es normal en las fases iniciales, porque los cambios óseos tardan una o dos semanas en aparecer, y solo sirve para descartar otras entidades como la epifisiólisis o el Perthes. La *resonancia* es más sensible para la osteomielitis asociada pero exige sedación y no está disponible de forma inmediata. El diagnóstico diferencial principal es la *sinovitis transitoria de cadera*, que cursa *sin fiebre alta* y con reactantes normales, y ahí residen los criterios de Kocher.',
  no:{0:'La radiografía es normal en las primeras fases y no detecta el derrame articular.',2:'La resonancia es más sensible para la osteomielitis, pero exige sedación y no es la prueba inicial.',3:'La artrografía es una técnica invasiva sin indicación en el diagnóstico de una artritis séptica.'},
  trampa:'Se pide radiografía por costumbre ante una cojera. En la sospecha de artritis séptica lo que hay que ver es líquido, y eso lo muestra la ecografía.',
  dx:['Artritis séptica de cadera','Sinovitis transitoria','Osteomielitis','Enfermedad de Perthes'],
  obj:'Elegir la ecografía como primera prueba en la cadera dolorosa febril del niño.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con Nelson, Tratado de Pediatría, y los criterios de Kocher.'
},
'MIR-2022-M107': {
  esp:'Cirugía', tema:'Traumatología', sub:'Fractura patológica inminente',
  clave:'Lesión lítica que ocupa TODO el diámetro del húmero con dolor incontrolado y supervivencia mayor de 2 años: fijación con clavo endomedular.',
  exp:'Ante una metástasis ósea hay que decidir si existe *riesgo inminente de fractura patológica*, y para ello se usan criterios como la *escala de Mirels*, que puntúa la localización, el tipo de lesión, el tamaño respecto al diámetro del hueso y el dolor. Este paciente reúne los factores de máximo riesgo: lesión *lítica*, que *afecta a la totalidad del diámetro* del hueso, y *dolor continuo mal controlado*, que es en sí mismo un signo de inestabilidad mecánica. Y hay un dato que decide la agresividad del tratamiento: una *supervivencia estimada superior a dos años*, es decir, el paciente va a vivir lo suficiente como para sufrir la fractura y sus consecuencias. La conducta correcta es la *fijación profiláctica con clavo endomedular acerrojado*, que estabiliza todo el hueso, permite el uso inmediato del brazo, controla el dolor y evita una fractura patológica cuya consolidación sería mala y cuya cirugía posterior resulta mucho más compleja; después se completa con radioterapia. Que el húmero no soporte carga no lo protege: sigue sometido a torsión y a tracción muscular.',
  no:{0:'Que no soporte carga no evita la fractura: el húmero sufre fuerzas de torsión y tracción muscular importantes.',1:'Los mórficos controlarían el dolor pero no la inestabilidad mecánica, y la fisioterapia sobre un hueso a punto de romperse es peligrosa.',2:'El yeso no estabiliza una lesión que ocupa todo el diámetro del hueso y produce rigidez y atrofia.'},
  trampa:'Se opta por paliar el dolor por tratarse de un paciente oncológico. Con dos años de supervivencia, fijar el hueso es lo que más calidad de vida aporta.',
  dx:['Metástasis ósea con fractura inminente','Mieloma','Fractura patológica establecida'],
  obj:'Indicar la fijación profiláctica en la lesión ósea metastásica con riesgo de fractura.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con la escala de Mirels y Campbell, Cirugía Ortopédica.'
},
'MIR-2021-M66': {
  esp:'Cirugía', tema:'Cirugía plástica', sub:'Contractura capsular',
  clave:'Prótesis mamaria que se endurece y se deforma años después: contractura capsular, la complicación más frecuente.',
  exp:'Toda prótesis mamaria queda envuelta por una *cápsula fibrosa* que el organismo forma alrededor de cualquier cuerpo extraño. Cuando esa cápsula se *engrosa y se retrae*, aparece la *contractura capsular*, que es la complicación tardía más frecuente de la mamoplastia de aumento. Su presentación es exactamente la del caso: aparición *progresiva* a lo largo de meses o años, *aumento de consistencia* de la mama, *deformidad* con desplazamiento del implante —típicamente hacia arriba y hacia el hueco axilar—, *asimetría* respecto a la mama contralateral y *molestias* con los movimientos del brazo. Se gradúa con la escala de *Baker*, del I al IV, y este caso corresponde a un grado III o IV. El tratamiento es quirúrgico, con *capsulectomía* y recambio del implante. Merece la pena conocer también la alternativa que la pregunta ofrece: el *linfoma anaplásico de células grandes asociado a implantes* es una entidad rara pero real, que se presenta de forma distinta, típicamente como un *seroma tardío* de aparición brusca o una masa, no como un endurecimiento progresivo.',
  no:{0:'El seroma crónico infectado cursaría con signos inflamatorios, aumento de volumen fluctuante y a menudo fiebre.',1:'El linfoma asociado a implantes se presenta como seroma tardío de aparición brusca o masa, no como endurecimiento progresivo.',3:'Un carcinoma daría una tumoración localizada, con posible retracción cutánea o adenopatías, no un endurecimiento global de la mama.'},
  trampa:'Se sospecha cáncer ante cualquier cambio en una mama. La contractura endurece la mama ENTERA de forma progresiva, que es un patrón distinto al de un tumor.',
  dx:['Contractura capsular','Linfoma anaplásico asociado a implante','Rotura de prótesis','Carcinoma de mama'],
  obj:'Reconocer la contractura capsular como complicación más frecuente de la prótesis mamaria.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con la escala de Baker y guías de cirugía plástica mamaria.'
},
'MIR-2021-M209': {
  esp:'Medicina Interna', tema:'Gastroenterología', sub:'Esófago de Barrett',
  clave:'Mucosa asalmonada ascendiendo en llamas MÁS epitelio metaplásico en la biopsia: esófago de Barrett.',
  exp:'El diagnóstico de esófago de Barrett exige dos requisitos y ambos se cumplen. El primero es *endoscópico*: la mucosa escamosa blanquecina del esófago aparece sustituida por una *mucosa asalmonada o rosada* que asciende desde la unión esofagogástrica con el aspecto característico de *lengüetas o llamas*. El segundo es *histológico*: la biopsia demuestra *epitelio metaplásico*, es decir, la sustitución del epitelio escamoso por epitelio *columnar de tipo intestinal*, con células caliciformes. Todo ello en un paciente con *pirosis de larga evolución*, que es el contexto esperable, ya que el Barrett es la consecuencia adaptativa de la agresión ácida crónica. La ausencia de displasia en las biopsias es una buena noticia y determina el intervalo de vigilancia, que es lo importante del diagnóstico: el Barrett es una lesión *premaligna* con riesgo de *adenocarcinoma de esófago*, de modo que obliga a inhibidores de la bomba de protones y a endoscopias de control periódicas. Los eosinófilos que menciona el enunciado pueden aparecer también en la esofagitis por reflujo; una *esofagitis eosinofílica* verdadera se presentaría con *disfagia e impactaciones*, y en la endoscopia con anillos, surcos longitudinales y exudados blanquecinos, no con mucosa asalmonada.',
  no:{1:'La esofagitis eosinofílica cursa con disfagia e impactación alimentaria, y en la endoscopia con anillos y surcos, no con mucosa asalmonada.',2:'La enfermedad por reflujo no erosiva se define por endoscopia NORMAL, y aquí hay una alteración evidente con metaplasia.',3:'La esofagitis grado B de Los Ángeles exige EROSIONES mucosas, que el enunciado niega expresamente.'},
  trampa:'La cifra de eosinófilos desvía hacia la esofagitis eosinofílica. Lo que define el Barrett es el aspecto asalmonado más la metaplasia, y ambos están presentes.',
  dx:['Esófago de Barrett','Esofagitis eosinofílica','Esofagitis por reflujo','Adenocarcinoma de esófago'],
  obj:'Diagnosticar el esófago de Barrett y entender su significado premaligno.',
  ref:'Examen MIR 2021, Ministerio de Sanidad de España. Contrastado con guías del American College of Gastroenterology sobre esófago de Barrett.'
},
'MIR-2022-M130': {
  esp:'Medicina Interna', tema:'Oncología', sub:'Hepatocarcinoma avanzado',
  clave:'Hepatocarcinoma multinodular con INVASIÓN PORTAL: estadio BCLC C. Tratamiento sistémico, no local.',
  exp:'La estadificación *BCLC* ordena el tratamiento del hepatocarcinoma cruzando la extensión del tumor, la función hepática y el estado general. Aquí hay *cuatro nódulos*, uno de 6 cm, y sobre todo *invasión de la vena porta*, que es un criterio de *estadio C o avanzado* y que descarta de plano todas las opciones locales. La *resección* y la *ablación con radiofrecuencia* se reservan para el estadio muy precoz o precoz, con uno o pocos nódulos pequeños y sin invasión vascular. El *trasplante* exige cumplir los *criterios de Milán* —un nódulo de hasta 5 cm o hasta tres de 3 cm—, y además la invasión vascular es una *contraindicación absoluta*. Y la *quimioembolización transarterial* corresponde al estadio intermedio, con enfermedad multinodular pero *sin invasión vascular* ni diseminación; realizarla con la porta invadida arriesga una isquemia hepática grave. Por eso el tratamiento es *sistémico*: el sorafenib, inhibidor multiquinasa, fue el primero en demostrar beneficio en supervivencia, aunque hoy la primera línea preferida es la combinación de atezolizumab con bevacizumab. La función hepática conservada, Child A-5, es lo que permite tratarlo.',
  no:{0:'La quimioembolización corresponde al estadio intermedio SIN invasión vascular, y aquí la porta está invadida.',2:'El trasplante exige cumplir los criterios de Milán, y la invasión vascular es contraindicación absoluta.',3:'La radiofrecuencia se reserva para tumores únicos y pequeños en estadio precoz.'},
  trampa:'Se busca un tratamiento local por ser más eficaz sobre el tumor. La invasión portal cambia el estadio y con él toda la estrategia.',
  dx:['Hepatocarcinoma estadio BCLC C','Colangiocarcinoma','Metástasis hepáticas'],
  obj:'Aplicar la clasificación BCLC para elegir el tratamiento del hepatocarcinoma.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con guías EASL sobre carcinoma hepatocelular.'
},
'MIR-2022-M131': {
  esp:'Medicina Interna', tema:'Oncología', sub:'Ictericia obstructiva maligna',
  clave:'Ictericia INDOLORA con pérdida de peso y estenosis ABRUPTA del colédoco distal: cáncer de páncreas.',
  exp:'Cada elemento del caso apunta en la misma dirección. El patrón analítico es *colestásico puro*: *bilirrubina directa* elevada con *fosfatasa alcalina y GGT* altas y *transaminasas normales*, lo que indica obstrucción de la vía biliar sin daño hepatocelular. La ecografía muestra *dilatación intra y extrahepática*, es decir, la obstrucción está *distal*, en el colédoco. Y la CPRE describe una *estenosis abrupta y corta del colédoco distal*, la imagen clásica de una compresión *extrínseca* por una masa en la cabeza del páncreas. Sobre todo eso se superpone la *tríada de alarma*: ictericia *indolora*, *pérdida de peso* y edad avanzada. La ausencia de dolor es especialmente significativa, porque la *coledocolitiasis* casi siempre duele —cólico biliar— y además suele producir una ictericia *fluctuante*, con dilatación menor. Lo que procede a continuación es una *TC con contraste en fase pancreática* para estadificar y valorar la resecabilidad, y aprovechar la CPRE para colocar una prótesis biliar si la cirugía se va a demorar.',
  no:{0:'La colangitis esclerosante primaria produce estenosis MÚLTIPLES y arrosariadas, y afecta sobre todo a varones jóvenes con colitis ulcerosa.',1:'La coledocolitiasis suele cursar con dolor cólico e ictericia fluctuante, y la CPRE mostraría el cálculo, no una estenosis abrupta.',3:'Una hepatitis aguda elevaría marcadamente las transaminasas y no dilataría la vía biliar.'},
  trampa:'Se piensa en cálculos por ser la causa más frecuente de ictericia obstructiva. La ausencia de dolor y la pérdida de peso cambian la probabilidad por completo.',
  dx:['Adenocarcinoma de páncreas','Coledocolitiasis','Colangiocarcinoma distal','Ampuloma'],
  obj:'Reconocer el patrón de ictericia obstructiva maligna y su diferencia con la litiásica.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con guías NCCN de cáncer de páncreas.'
},
'MIR-2022-M126': {
  esp:'Medicina Interna', tema:'Neumología', sub:'Escala CRB-65',
  clave:'CRB-65: frecuencia respiratoria de 32 suma 1 y la edad de 72 suma otro. Total 2 puntos, que puede requerir ingreso.',
  exp:'La escala *CRB-65* valora la gravedad de la neumonía adquirida en la comunidad sin necesidad de analítica, lo que la hace muy útil en atención primaria, y puntúa un punto por cada uno de estos cuatro criterios: *C* de confusión, *R* de frecuencia respiratoria igual o superior a 30, *B* de presión arterial sistólica menor de 90 o diastólica igual o menor de 60, y *65* de edad igual o superior a 65 años. Aplicándola a este paciente: *no hay confusión*, ya que está orientado y con buen nivel de conciencia, de modo que no suma; la *frecuencia respiratoria es de 32*, es decir, mayor de 30, y suma *1*; la tensión de *110/75* no cumple ninguno de los dos umbrales y no suma; y la *edad de 72 años* suma *1*. El total es de *2 puntos*. La interpretación es la siguiente: *0 puntos* significa mortalidad baja y manejo ambulatorio; *1 o 2 puntos* implican riesgo intermedio y valoración individualizada de ingreso, que es lo que dice la respuesta correcta; y *3 o 4 puntos* obligan a ingreso, valorando incluso la unidad de cuidados intensivos. Su versión hospitalaria, el CURB-65, añade la urea.',
  no:{0:'Con 0 puntos el paciente sería de bajo riesgo, pero suma por la frecuencia respiratoria y por la edad.',1:'Solo suma 1 punto quien cumpla un único criterio; aquí cumple dos.',3:'Para 3 puntos haría falta un criterio más, como confusión o hipotensión, que no están presentes.'},
  trampa:'Se cuenta la tensión de 110/75 como baja. El umbral es sistólica menor de 90 o diastólica igual o menor de 60: aquí no se cumple ninguno.',
  dx:['Neumonía adquirida en la comunidad'],
  obj:'Calcular e interpretar la escala CRB-65.',
  ref:'Examen MIR 2022, Ministerio de Sanidad de España. Contrastado con guías BTS e IDSA/ATS sobre neumonía adquirida en la comunidad.'
}

});
